window.VIBE_LESSONS=[{"title": "Dall’idea al primo quiz interattivo", "intro": "Trasforma un bisogno di apprendimento in un piccolo quiz. Imparerai a specificare il risultato, generare una prima versione, provarla e migliorarla.", "product": "Un quiz di tre domande con feedback, punteggio e riavvio.", "goals": ["Distinguere un obiettivo didattico da una funzione dell’app.", "Scrivere un prompt con destinatari, obiettivo e vincoli.", "Provare il prototipo prima di usarlo."], "example": {"kind": "Quiz interattivo", "audience": "Studenti di seconda liceo", "goal": "Distinguere fonti storiche primarie e secondarie", "features": "Tre domande con una sola risposta corretta, spiegazione dopo la risposta, punteggio e riavvio"}, "steps": [{"title": "1. Scegli che cosa vuoi far imparare", "explain": "Parti dal bisogno di apprendimento e descrivi un’attività osservabile. «Un’app di storia» lascia molte decisioni al modello; «classificare tre fonti e motivare la scelta» permette di definire funzioni e prove. La sezione iniziale chiarisce che cosa intendiamo per vibe coding e come useremo la verifica nel corso.", "prompt": "Aiutami a definire un’attività per [destinatari] su [argomento]. L’obiettivo è [azione osservabile]. Proponi una sola funzione principale e tre criteri con cui verificare se serve all’obiettivo. Non scrivere ancora il codice.", "action": "Completa: «L’utente deve imparare a…; l’app gli permette di…».", "check": "L’obiettivo descrive un apprendimento; la funzione descrive un’azione nell’app."}, {"title": "2. Scrivi una richiesta verificabile", "explain": "Specifica destinatari, obiettivo, funzioni e vincoli. Usa contenuti dimostrativi e non dati reali degli studenti.", "prompt": "Crea un quiz per [destinatari] sull’obiettivo [obiettivo]. Deve avere tre domande, quattro opzioni e una sola risposta corretta per domanda, spiegazione dopo la risposta, punteggio e riavvio. Prima descrivi il comportamento e i criteri di verifica. Non aggiungere login o raccolta dati.", "action": "Sostituisci tutti i campi tra parentesi e controlla che le funzioni siano numerabili.", "check": "Per ogni funzione sai dire quale risultato ti aspetti."}, {"title": "3. Chiedi la prima versione e aprila", "explain": "HTML organizza i contenuti, CSS ne definisce l’aspetto e JavaScript gestisce le interazioni. Per iniziare puoi richiedere tutto in un singolo file.", "prompt": "Usa la specifica concordata per generare un unico file HTML completo con CSS e JavaScript incorporati, adatto a smartphone e computer. Spiega come salvarlo come quiz.html e aprirlo nel browser. Usa dati fittizi e nessuna dipendenza esterna. Distingui il codice generato dai test realmente eseguiti.", "action": "Salva il file con estensione .html e aprilo nel browser.", "check": "Vedi tre domande e puoi scegliere una risposta senza installare altri strumenti."}, {"title": "4. Prova prima di fidarti", "explain": "Una pagina che si apre non è ancora un quiz verificato. Controlla sia le risposte disciplinari sia punteggio e riavvio.", "prompt": "Proponi cinque test riproducibili per il quiz: risposta corretta, risposta errata, tentativo di invio senza scelta, punteggio finale e riavvio. Per ciascuno indica azione e risultato atteso. Non dichiarare di averli eseguiti.", "action": "Esegui i test e annota risultato atteso, osservato ed esito.", "check": "Controlli il punteggio anche dopo una risposta errata e dopo il riavvio."}, {"title": "5. Migliora un aspetto e riprova", "explain": "Una modifica circoscritta permette di capire che cosa è cambiato. Dopo una correzione ripeti anche i test precedenti.", "prompt": "Aggiungi una spiegazione disciplinare dopo ogni risposta, senza cambiare domande, punteggio o riavvio. Indica quali parti modifichi e quali test devo ripetere. Se trovi dati mancanti, chiedimeli.", "action": "Confronta prima e dopo. Conserva il file, il prompt iniziale e il registro dei test.", "check": "Sai distinguere ciò che hai deciso, ciò che l’IA ha generato e ciò che hai effettivamente verificato."}], "quiz": [{"case": "Una collega di Storia ti propone quattro formulazioni per il suo primo quiz. Quale è un obiettivo da cui puoi ricavare funzioni e prove?", "options": ["Gli studenti conosceranno meglio il Novecento grazie a un quiz coinvolgente e moderno.", "Gli studenti classificheranno tre fonti come primarie o secondarie, motivando la scelta.", "L’app proporrà tre domande con spiegazione, punteggio e riavvio alla fine di ogni percorso svolto.", "Gli studenti useranno uno strumento interattivo per ripassare la storia in autonomia."], "correct": 1, "feedback": "Classificare e motivare sono azioni osservabili: da qui derivano le domande e i criteri per controllarle.", "hint": "Cerca la formulazione che descrive che cosa fa lo studente, e che tu puoi osservare.", "why": ["«Conoscere meglio» non è osservabile: non dice quale prova mostrerà l’apprendimento.", "", "Descrive le funzioni dell’app, non che cosa deve imparare lo studente.", "Descrive l’uso di uno strumento, non un apprendimento verificabile."]}, {"case": "Tu e un collega usate lo stesso prompt e ottenete due quiz diversi: in uno il punteggio è sempre visibile, nell’altro compare solo alla fine. Che cosa fate?", "options": ["Scegliete la versione con la grafica migliore: il comportamento di fondo è comunque lo stesso.", "Rigenerate finché le due versioni coincidono, così il prompt diventa affidabile e ripetibile.", "Provate entrambe con gli stessi test ricavati dalla specifica e tenete quella che li supera.", "Allungate il prompt con più dettagli, perché un prompt completo produce sempre lo stesso codice."], "correct": 2, "feedback": "La variabilità è normale: sono i criteri e i test decisi prima a rendere confrontabili due versioni.", "hint": "Pensa a che cosa resta costante tra due generazioni dello stesso prompt.", "why": ["Due versioni possono comportarsi in modo diverso anche con la stessa grafica: va provato.", "La variabilità è propria del modello: rigenerare non la elimina, sposta solo il problema.", "", "Più dettagli riducono le differenze ma non le annullano: la verifica resta necessaria."]}, {"case": "Gli studenti useranno in classe il quiz generato con l’IA, salvato come unico file HTML. Che cosa devi controllare per tutelare le loro risposte?", "options": ["Nulla: le risposte restano nell’account dell’assistente che ha generato il file del quiz.", "Che il codice non invii dati a servizi esterni: in quel caso le risposte restano nel browser.", "Che gli studenti abbiano un account istituzionale, perché il quiz interroga l’IA a ogni risposta.", "Che l’assistente abbia attiva l’opzione privacy, perché riceve le risposte durante l’uso."], "correct": 1, "feedback": "L’IA lavora mentre costruisci; durante l’uso il browser esegue il codice. Va verificato che il codice non trasmetta dati.", "hint": "Distingui il momento in cui l’IA scrive il codice dal momento in cui la classe usa il file.", "why": ["Il file non è collegato all’assistente: ciò che conta è che cosa fa il codice nel browser.", "", "Un quiz autonomo non interroga l’IA durante l’uso: gli account degli studenti non servono.", "L’assistente non riceve nulla durante l’uso di un file autonomo: il controllo riguarda il codice."]}, {"case": "Quale requisito, scritto nel prompt, puoi verificare con una prova precisa e ripetibile?", "options": ["Le spiegazioni devono essere chiare e calibrate sul livello della classe.", "Dopo il riavvio il punteggio torna a zero e compare la prima domanda.", "L’interfaccia deve risultare intuitiva anche per chi usa poco il computer.", "Il quiz deve motivare gli studenti a ripassare volentieri a casa."], "correct": 1, "feedback": "Un requisito verificabile indica un’azione e un risultato atteso che chiunque può controllare.", "hint": "Cerca il requisito per cui sai dire esattamente quale azione compiere e che cosa deve succedere.", "why": ["«Chiare» e «calibrate» richiedono criteri espliciti: così com’è non si prova con un’azione.", "", "«Intuitiva» è un giudizio: va tradotta in compiti osservabili prima di poterla provare.", "La motivazione non si verifica con una prova sul software."]}, {"case": "Per provare il quiz vuoi domande realistiche. Quale materiale puoi inserire nel prompt?", "options": ["Il file dei risultati dell’ultima verifica, con le iniziali degli studenti al posto dei nomi.", "Tre domande scritte apposta, con risposte che hai controllato su fonti affidabili.", "Un estratto del registro con nomi inventati, ma con voti e assenze reali della classe.", "Le domande di un manuale scolastico copiate per intero, citando il volume come fonte."], "correct": 1, "feedback": "Contenuti dimostrativi scritti da te e verificati: nessun dato personale e nessun problema di diritti.", "hint": "Chiediti se il materiale contiene dati riconducibili agli studenti o testi di altri autori.", "why": ["Iniziali e risultati restano dati personali riconducibili agli studenti.", "", "Voti e assenze reali sono dati personali anche con nomi inventati.", "Copiare per intero un manuale pone un problema di diritti d’autore, anche citandolo."]}, {"case": "Per il primo prototipo l’IA propone un framework, un server locale e un database «per far crescere il progetto». Che cosa chiedi?", "options": ["Di procedere: un’architettura completa evita di rifare tutto quando il quiz crescerà.", "Un unico file HTML con CSS e JavaScript incorporati e nessuna dipendenza esterna.", "Di tenere il framework ma togliere il database, così il quiz resta comunque scalabile.", "Di installare prima gli strumenti sul PC del laboratorio e poi generare il codice."], "correct": 1, "feedback": "Un file autonomo si apre ovunque, anche offline, e si verifica in pochi minuti: è il prototipo adatto.", "hint": "Pensa a che cosa serve davvero per provare tre domande con punteggio e riavvio.", "why": ["Complica il prototipo prima di sapere se funziona: più parti da verificare e da mantenere.", "", "Anche il solo framework aggiunge installazioni e dipendenze non necessarie per tre domande.", "Installare strumenti sul laboratorio non serve a un quiz che può stare in un solo file."]}, {"case": "Il quiz generato contiene queste due funzioni. Quale test del registro fa emergere il difetto?", "code": "let punti = 0;\nfunction rispondi(scelta, corretta) {\n  if (scelta === corretta) punti = punti + 1;\n}\nfunction riavvia() {\n  domanda = 0;\n  mostraDomanda();\n}", "options": ["Rispondere correttamente alla prima domanda e controllare il feedback mostrato.", "Completare il quiz, riavviarlo e controllare il punteggio con cui riparte.", "Premere Invia senza scegliere un’opzione e controllare il messaggio che compare.", "Rispondere in modo errato e controllare che il punteggio resti invariato."], "correct": 1, "feedback": "riavvia() riporta alla prima domanda ma non azzera punti: lo scopre solo il test del riavvio.", "hint": "Leggi che cosa modifica riavvia() e che cosa invece lascia com’è.", "why": ["Questo test passa: la risposta corretta aumenta il punteggio come previsto.", "", "Verifica un comportamento diverso, che queste due funzioni non gestiscono.", "Questo test passa: con una scelta errata il punteggio non cambia."]}, {"case": "Alla fine della generazione l’IA scrive: «Ho testato il quiz e funziona correttamente». Qual è la reazione adeguata?", "options": ["Ne prendi atto e passi al controllo dei contenuti, perché quello tecnico risulta già svolto.", "Chiedi quali test dichiara di aver fatto, poi li esegui tu e annoti l’esito osservato.", "Le chiedi di ripetere il test con più attenzione e di confermare il risultato ottenuto.", "Apri il file: se la prima domanda compare correttamente, consideri il test confermato."], "correct": 1, "feedback": "La dichiarazione dell’IA è un’ipotesi: contano le prove che esegui tu, con atteso, osservato ed esito.", "hint": "Chiediti chi ha osservato davvero il comportamento del quiz.", "why": ["Un modello genera testo plausibile anche quando descrive test: non è una prova eseguita.", "", "Una seconda conferma dell’IA resta un testo generato, non un’osservazione.", "Che la pagina si apra non dice nulla su punteggio, feedback e riavvio."]}, {"case": "Il quiz supera tutti i test tecnici, ma una spiegazione attribuisce un documento all’anno sbagliato. Come procedi?", "options": ["Chiedi all’IA di ricontrollare la data e accetti la correzione che ti propone.", "Correggi la spiegazione su una fonte verificata e ripeti i test sul quiz modificato.", "Lo usi comunque: i test tecnici superati indicano che il quiz è pronto per la classe.", "Elimini la domanda e ne fai generare un’altra sullo stesso argomento."], "correct": 1, "feedback": "Il contenuto disciplinare è responsabilità del docente: si corregge su una fonte e si riprova la nuova versione.", "hint": "Distingui la verifica tecnica da quella disciplinare: chi garantisce la seconda?", "why": ["Affidi la verifica alla stessa fonte che ha prodotto l’errore.", "", "Un quiz che funziona può contenere errori di contenuto: sono due verifiche diverse.", "La nuova domanda è contenuto non ancora verificato: il problema si ripresenta."]}, {"case": "Un collega vuole riutilizzare il tuo quiz con le sue classi. Quale documentazione gli permette di fidarsi del prodotto?", "options": ["Il file HTML e il prompt finale, da cui il collega può rigenerare lo stesso quiz quando gli serve.", "Il file, l’obiettivo, i test con atteso, osservato ed esito e i limiti ancora aperti.", "Il file e una nota con il nome dell’assistente IA e la versione del modello usato.", "Il file e la cronologia completa della chat, da cui ricostruire ogni scelta fatta."], "correct": 1, "feedback": "Obiettivo, prove eseguite e limiti permettono a un collega di ripetere le verifiche sulla stessa versione.", "hint": "Pensa a che cosa serve per ripetere le tue prove, non per rifare il quiz.", "why": ["Rigenerare dal prompt produce una versione diversa, non quella che hai collaudato.", "", "Nome e versione del modello non dicono nulla su che cosa è stato verificato.", "La cronologia è lunga e non distingue ciò che è stato davvero provato."]}], "id": 1, "version": 3, "concepts": [{"title": "Che cosa significa vibe coding", "text": "Il termine indica un modo di costruire prototipi dialogando con un modello che genera codice. Nella sua accezione originaria si delega anche molta lettura del codice. In questo corso usiamo la prototipazione come punto di partenza e la completiamo con comprensione, revisione e test prima dell’uso in classe. La distinzione è discussa da Simon Willison [1]."}, {"title": "Come funziona il dialogo", "text": "Il modello produce codice a partire dalle istruzioni e dal contesto della conversazione. Può introdurre errori o ipotesi non richieste. Il browser esegue il codice; tu osservi il comportamento e descrivi la differenza rispetto all’atteso. Due generazioni dello stesso prompt possono dare risultati diversi."}, {"title": "Che cosa resta nelle tue mani", "text": "Scegli obiettivo, esempi e criteri di correttezza. L’IA propone un’implementazione. Chiedile di spiegare input, regole e output; verifica la spiegazione e fai riesaminare le parti che non comprendi. Un quiz a correzione fissa può funzionare dopo la generazione senza usare un’IA durante l’esecuzione."}], "disciplineExamples": [{"area": "Italiano", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere similitudine e metafora in sei brevi esempi originali controllati dal docente", "features": "Scelte, motivazione dopo la risposta e riavvio", "evidence": "Classifica un nuovo esempio e motiva la scelta.", "case": {"probe": "Classifica e motiva: «Il tuo sorriso è una finestra aperta sul mattino».", "full": "«È una metafora: il sorriso è paragonato a una finestra senza parole di paragone come “come” o “simile a”.»", "partial": "«È una metafora, perché è una figura poetica.»", "why": "L’etichetta è giusta ma il criterio manca: “figura poetica” vale anche per la similitudine. Potrebbe aver indovinato."}}, {"area": "Storia e filosofia", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere fonti primarie e secondarie in esempi con contesto dichiarato", "features": "Tre fonti predisposte dal docente, scelta, motivazione e riavvio", "evidence": "Classifica una fonte nuova rispetto al quesito storico indicato.", "case": {"probe": "Quesito: come vivevano i soldati in trincea nel 1916? Fonte: lettera di un fante alla famiglia, scritta dal fronte nel 1916.", "full": "«È primaria: l’ha scritta un testimone diretto nel periodo studiato e risponde al quesito con la sua esperienza.»", "partial": "«È primaria perché è una lettera.»", "why": "Il tipo di documento non decide: una lettera scritta oggi da uno storico sarebbe secondaria. Il criterio è il rapporto tra fonte, evento e quesito."}}, {"area": "Lingue straniere", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Scegliere tempi verbali adeguati in situazioni comunicative B1", "features": "Frasi originali, contesto sufficiente, una scelta univoca e motivazione", "evidence": "Scegli la forma in un nuovo contesto e spiega l’indizio temporale.", "case": {"probe": "Completa: «I ___ (live) in Rome since 2019».", "full": "«have lived (o have been living): l’azione è iniziata nel passato e continua ora; l’indizio è since.»", "partial": "«lived, perché il 2019 è passato.»", "why": "Coglie il riferimento al passato ma non il legame con il presente segnalato da since: è l’errore tipico di chi traduce dall’italiano «vivo a Roma dal 2019»."}}, {"area": "Matematica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Confrontare frazioni con denominatori positivi", "features": "Tre casi, spiegazione del confronto, punteggio e riavvio", "evidence": "Ordina una nuova coppia e spiega il criterio.", "case": {"probe": "Ordina 3/4 e 5/7.", "full": "«3/4 > 5/7: con denominatore comune 28 ottengo 21/28 e 20/28, quindi vince 3/4.»", "partial": "«5/7 è più grande perché 5 e 7 sono più grandi di 3 e 4.»", "why": "Confronta numeratori e denominatori come numeri separati: è l’errore tipico che il quiz deve far emergere."}}, {"area": "Scienze e fisica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere osservazione, ipotesi e conclusione in casi sperimentali brevi", "features": "Casi originali verificati, scelta e motivazione", "evidence": "Classifica una nuova frase e spiega la decisione.", "case": {"probe": "Classifica: «Le piantine tenute al buio sono diventate gialle e più alte di quelle alla luce».", "full": "«È un’osservazione: descrive ciò che si è visto e misurato, senza spiegarne la causa.»", "partial": "«È una conclusione, perché dice com’è andato l’esperimento.»", "why": "Confonde il risultato osservato con la sua interpretazione: una conclusione direbbe perché le piantine sono cambiate."}}, {"area": "Arte e musica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere elementi formali in esempi descritti o materiali autorizzati", "features": "Schede validate dal docente, una scelta univoca e motivazione", "evidence": "Indica un elemento formale in un esempio nuovo.", "case": {"probe": "In un dipinto le linee del pavimento e del soffitto convergono in un unico punto al centro, dietro la figura principale. Quale elemento formale riconosci?", "full": "«La prospettiva lineare centrale: le linee in profondità convergono nel punto di fuga, che qui guida lo sguardo verso la figura.»", "partial": "«La profondità, perché sembra tridimensionale.»", "why": "Descrive l’effetto ma non nomina l’elemento formale né l’indizio visibile che lo rivela."}}, {"area": "Informatica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere input, elaborazione e output in piccoli programmi", "features": "Tre casi, traccia e feedback che spiega la sequenza", "evidence": "Ricostruisci l’output di un caso nuovo.", "case": {"probe": "a = 4\nb = a * 2\nprint(a + b)\nQuale output?", "full": "«12. Input: a vale 4; elaborazione: b diventa 8, poi si calcola a + b; output: 12.»", "partial": "«8.»", "why": "Si ferma all’ultima assegnazione e confonde il valore di b con ciò che viene stampato: non segue la sequenza fino all’output."}}, {"area": "Diritto ed economia", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Collocare una norma nella gerarchia delle fonti del diritto", "features": "Tre norme descritte dal docente (Costituzione, legge, regolamento), una scelta univoca e motivazione", "evidence": "Colloca una norma nuova nella gerarchia e motiva la scelta.", "case": {"probe": "Il Governo, in un caso straordinario di necessità e urgenza, adotta un decreto-legge. Dove lo collochi?", "full": "«Tra le fonti primarie, allo stesso livello della legge ordinaria. Ha forza di legge (art. 77 Cost.), quindi sta sotto la Costituzione e sopra i regolamenti.»", "partial": "«Sotto la Costituzione», senza spiegare perché; oppure «sotto la legge, perché lo fa il Governo».", "why": "La seconda risposta mostra un errore tipico: confondere chi emana l’atto con la forza che l’atto ha."}}, {"area": "Disegno e storia dell’arte", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere gli ordini architettonici classici da elementi descritti", "features": "Tre schede descritte dal docente (capitello, base, fusto), una scelta univoca e motivazione", "evidence": "Riconosci l’ordine di un edificio nuovo indicando l’elemento decisivo.", "case": {"probe": "Colonna con capitello a volute, base modanata, fusto scanalato e slanciato. Quale ordine?", "full": "«Ionico: lo riconosco dalle volute del capitello. La presenza della base esclude anche il dorico, che poggia direttamente sullo stilobate.»", "partial": "«Corinzio, perché è elegante e slanciato.»", "why": "Giudica l’impressione d’insieme invece dell’elemento diagnostico: il capitello corinzio è a foglie d’acanto, non a volute."}}], "promptContrast": {"weak": "Fammi un quiz bello.", "reason": "Mancano destinatari, obiettivo, contenuti controllati e comportamento da verificare."}, "schedule": "20 min · Che cos’è il vibe coding e come funziona (guida al corso) · 30 min · confronto tra prompt vago e prompt specifico · 70 min · laboratorio: primo quiz nella propria disciplina · 10 min pausa · 35 min · test incrociati tra colleghi · 35 min · progettazione dell’attività in classe (modalità A) · 10 min pausa · 30 min · test finale e domande aperte.", "classroom": {"mode": "A", "modeLabel": "Modalità A · Il docente costruisce, la classe usa", "title": "Il quiz «con un errore nascosto»", "intro": "Gli studenti non usano l’IA e non hanno bisogno di account: usano il quiz che hai generato e verificato. L’attività rende visibile ai ragazzi ciò che hai imparato oggi: un prodotto che funziona non è per questo corretto.", "steps": [["5 min · Previsione", "Presenta il quiz e chiedi di prevedere quale domanda sarà la più difficile e perché."], ["10 min · Uso", "Le coppie svolgono il quiz. Uno risponde, l’altro annota i dubbi su domande e spiegazioni."], ["10 min · Caccia all’errore", "Rivela che una spiegazione contiene un’imprecisione voluta, scelta da te: le coppie la cercano e la correggono motivando."], ["5 min · Riflessione", "Raccogli una correzione per coppia e chiedi: chi è responsabile del contenuto di un’app generata con l’IA?"]], "assess": "Valuta la correttezza disciplinare delle correzioni e la qualità della motivazione, non la velocità nel quiz."}}, {"title": "Progettare una lezione interattiva", "intro": "Costruisci una lezione digitale che accompagni chi studia: spiegazione breve, esempio, esercizio e feedback. Trasforma il percorso in requisiti prima di chiedere il codice.", "product": "Una lezione web con quattro passaggi, esercizio e feedback motivato.", "goals": ["Scomporre un percorso in passaggi progressivi.", "Definire azioni e criteri di accettazione.", "Costruire prompt coerenti tra contenuti e interfaccia."], "example": {"kind": "Lezione interattiva", "audience": "Studenti di prima liceo", "goal": "Confrontare due frazioni con denominatore diverso", "features": "Spiegazione breve, esempio svolto, esercizio autonomo, feedback motivato e navigazione avanti e indietro"}, "steps": [{"title": "1. Definisci risultato e prerequisiti", "explain": "Una lezione efficace non è un lungo testo su schermo. Parti da ciò che l’utente sa già e da ciò che deve saper fare alla fine.", "prompt": "Progetta una lezione su [argomento] per [destinatari]. Prerequisiti: [conoscenze]. Risultato osservabile: [azione]. Proponi quattro passaggi: spiegazione breve, esempio svolto, esercizio, feedback. Non scrivere ancora codice.", "action": "Scrivi un obiettivo e due prerequisiti.", "check": "Ogni passaggio prepara il successivo senza richiedere conoscenze non dichiarate."}, {"title": "2. Descrivi il percorso dell’utente", "explain": "Chiarisci cosa vede l’utente, cosa fa e cosa succede dopo. Il flusso deve prevedere anche errori e ritorni.", "prompt": "Per i quattro passaggi concordati descrivi: contenuto visibile, azione dell’utente, risposta del sistema e navigazione. Prevedi una risposta errata e la possibilità di tornare all’esempio senza perdere l’esercizio.", "action": "Disegna su carta le quattro schermate e collegale con frecce.", "check": "Non esistono pulsanti senza un comportamento definito."}, {"title": "3. Formula criteri di accettazione", "explain": "«Deve essere intuitiva» non basta. Un criterio utile si può provare, per esempio controllando il mantenimento della risposta dopo un ritorno.", "prompt": "Trasforma i requisiti in una tabella con requisito, prova e risultato atteso. Includi feedback motivato, ritorno all’esempio, ripresa dell’esercizio e uso da tastiera. Se un requisito è ambiguo, proponi una formulazione verificabile.", "action": "Scegli quattro criteri indispensabili e rimanda le funzioni opzionali.", "check": "Un’altra persona può ripetere le prove senza chiederti che cosa intendevi."}, {"title": "4. Genera una prima versione essenziale", "explain": "Chiedi al modello di usare la specifica e di non cambiare l’obiettivo durante lo sviluppo.", "prompt": "Genera la lezione concordata in un unico file HTML con CSS e JavaScript. Mantieni testi brevi, pulsanti con etichette esplicite e input etichettati. Non aggiungere account, classifiche o tracciamento. Fornisci istruzioni di apertura e piano di test.", "action": "Apri la lezione come se fossi un nuovo utente e percorri tutte le schermate.", "check": "Il flusso è completo anche quando sbagli l’esercizio."}, {"title": "5. Rivedi il feedback con una modifica mirata", "explain": "Il feedback deve aiutare a capire l’errore, senza limitarsi a mostrare «sbagliato».", "prompt": "Quando la risposta all’esercizio è errata, aggiungi un suggerimento che richiami il passaggio pertinente dell’esempio, senza svelare subito il risultato. Mantieni invariati navigazione e stato dell’esercizio. Elenca i test di regressione.", "action": "Prova risposta corretta, errata e ritorno all’esempio.", "check": "Il suggerimento è coerente con l’errore e le risposte restano conservate durante la navigazione."}], "quiz": [{"case": "Quale schermata trasforma un contenuto in un’attività di apprendimento?", "options": ["Tre paragrafi sulle cause della Prima guerra mondiale, con immagini e glossario.", "Un video di cinque minuti seguito da un riassunto scaricabile in PDF.", "Tre brevi fonti da collegare ciascuna a una causa, con una motivazione scritta.", "Una mappa concettuale animata che si espande quando si fa clic su ogni nodo."], "correct": 2, "feedback": "Un’attività chiede una decisione o una produzione che mostra la comprensione.", "hint": "Cerca la schermata in cui lo studente deve decidere o produrre qualcosa di osservabile.", "why": ["È un contenuto ben presentato: lo studente legge, ma non decide nulla.", "Video e riassunto espongono informazioni senza chiedere una decisione.", "", "Cliccare per espandere è interazione, non una decisione che mostri comprensione."]}, {"case": "Progetti una lezione sulla somma di frazioni con denominatori diversi. Che cosa specifichi per primo all’IA?", "options": ["Lo stile grafico e il numero di schermate, per evitare che la lezione risulti lunga.", "Ciò che gli studenti sanno già fare e ciò che dovranno saper fare alla fine.", "Che la lezione deve essere completa e coprire tutti i casi di somma possibili.", "Che la lezione deve sostituire la spiegazione in classe per gli studenti assenti."], "correct": 1, "feedback": "Prerequisiti e risultato atteso definiscono il percorso: il resto ne deriva.", "hint": "Una lezione parte da un punto e arriva a un altro: quali sono?", "why": ["Grafica e numero di schermate vengono dopo aver chiarito da dove parte e dove arriva lo studente.", "", "«Tutti i casi» allarga il perimetro senza dire che cosa lo studente deve saper fare.", "È un uso possibile, ma non dice all’IA quale apprendimento progettare."]}, {"case": "Nella specifica hai descritto in ordine le quattro schermate della lezione. Che cosa manca più spesso a questo punto?", "options": ["Il testo esatto di ogni pulsante, da fissare prima di generare il codice.", "Che cosa succede quando lo studente sbaglia o torna a una schermata precedente.", "Le animazioni di passaggio tra una schermata e la successiva.", "Il numero massimo di studenti che possono usare la lezione nello stesso momento."], "correct": 1, "feedback": "Il percorso reale include errori e ritorni: se non sono specificati, li decide il modello.", "hint": "Pensa a uno studente che non segue il percorso ideale.", "why": ["Le etichette si possono rifinire dopo: non cambiano il comportamento della lezione.", "", "Le animazioni non incidono sul percorso di apprendimento.", "Per una pagina statica nel browser il numero di utenti non è un vincolo di progetto."]}, {"case": "Quale criterio di accettazione puoi verificare con una prova?", "options": ["La lezione deve essere intuitiva e piacevole da seguire per tutta la classe.", "Il feedback deve risultare motivante e non scoraggiare mai lo studente.", "Tornando all’esercizio 2, la risposta già data deve ricomparire nel campo.", "La lezione deve funzionare bene per tutti gli studenti, anche i più fragili."], "correct": 2, "feedback": "Il criterio indica un’azione e un risultato osservabile: si prova in pochi secondi.", "hint": "Per quale criterio sai dire quale azione fare e che cosa deve succedere?", "why": ["«Intuitiva» e «piacevole» sono giudizi: vanno tradotti in compiti osservabili.", "«Motivante» non si prova con un’azione sull’app: serve un criterio esplicito.", "", "È un obiettivo condivisibile, ma non indica una prova da eseguire."]}, {"case": "Allo studente che risponde 3/7 all’esercizio «2/3 + 1/4», quale feedback lo aiuta a riprendere il ragionamento senza dargli la soluzione?", "options": ["Sbagliato. La risposta corretta è 11/12: confrontala con la tua e cerca la differenza.", "Non proprio: ricontrolla con calma tutti i calcoli, passaggio per passaggio, e poi riprova da capo.", "Hai sommato numeratori e denominatori: prima porta le frazioni allo stesso denominatore.", "Attenzione: le frazioni sono facili se ti concentri bene, prova di nuovo con calma."], "correct": 2, "feedback": "Il feedback nomina l’errore commesso e indica il passaggio da riprendere.", "hint": "Un buon indizio indica il passaggio del ragionamento da rivedere.", "why": ["Dà la soluzione: lo studente non ha modo di ricostruire il procedimento.", "È generico: non indica dove sta l’errore.", "", "Incoraggia, ma non dà alcuna informazione sul ragionamento."]}, {"case": "Nella lezione di Italiano lo studente scrive con parole sue la tesi di un testo. Come deve gestire la risposta l’app?", "options": ["Confrontandola con un elenco di parole chiave e assegnando il punto se ne trova almeno tre.", "Inviandola all’IA durante l’uso, perché valuti in tempo reale se la tesi è corretta.", "Mostrando i criteri e una risposta modello, e lasciando la valutazione al docente.", "Accettando ogni risposta di almeno venti parole, per non scoraggiare lo studente."], "correct": 2, "feedback": "Per risposte interpretative servono criteri espliciti e la revisione umana.", "hint": "Pensa a una risposta corretta scritta con parole diverse da quelle previste.", "why": ["Le parole chiave premiano chi le ripete e penalizzano chi formula bene con altre parole.", "Invia testi degli studenti a un servizio esterno e delega la valutazione al modello.", "", "La lunghezza non dice nulla sulla correttezza della tesi."]}, {"case": "Come distribuisci gli aiuti lungo la lezione?", "options": ["Lo stesso indizio dettagliato in ogni esercizio, così nessuno resta indietro.", "Indizi nei primi esercizi e una prova finale con meno aiuti.", "Nessun indizio, per non influenzare il ragionamento degli studenti.", "La soluzione completa disponibile in ogni esercizio con un pulsante."], "correct": 1, "feedback": "Gli aiuti si riducono progressivamente: la prova finale mostra l’autonomia raggiunta.", "hint": "Che cosa vuoi osservare alla fine della lezione?", "why": ["Aiuti costanti non permettono di vedere se lo studente è diventato autonomo.", "", "Senza aiuti iniziali chi è in difficoltà non ha modo di riprendere il ragionamento.", "Una soluzione sempre disponibile scoraggia il ragionamento."]}, {"case": "Nella prima versione l’IA ha aggiunto un timer e una classifica tra studenti «per aumentare il coinvolgimento». Che cosa fai?", "options": ["Li tieni: rendono la lezione più dinamica e non toccano in alcun modo l’obiettivo didattico.", "Tieni il timer e togli la classifica, che richiederebbe i nomi degli studenti.", "Li togli e chiedi una versione essenziale che rispetti la specifica concordata.", "Li tieni, ma li disattivi solo per gli studenti più fragili con un’opzione."], "correct": 2, "feedback": "La prima versione realizza la specifica: le aggiunte non richieste cambiano l’attività e vanno tolte.", "hint": "Confronta ciò che l’IA ha prodotto con ciò che avevi chiesto.", "why": ["Timer e classifica cambiano l’attività: premiano la velocità invece del ragionamento.", "Anche il timer non è stato chiesto e sposta l’attenzione sulla velocità.", "", "Mantiene funzioni non richieste e aggiunge un’opzione da gestire e verificare."]}, {"case": "Questa funzione gestisce il pulsante Indietro della lezione. Quale criterio di accettazione viola?", "code": "function vaiA(n) {\n  passo = n;\n  document.getElementById('risposta').value = '';\n  mostraPasso(passo);\n}", "options": ["Il feedback compare solo dopo che lo studente ha inviato la risposta.", "La risposta già data resta visibile quando si torna a un passaggio.", "Ogni passaggio mostra il proprio titolo e la propria consegna.", "Il pulsante Avanti è raggiungibile e attivabile da tastiera."], "correct": 1, "feedback": "La riga che assegna una stringa vuota cancella la risposta a ogni cambio di passaggio.", "hint": "Guarda che cosa accade al campo «risposta» quando si cambia passaggio.", "why": ["Questa funzione non gestisce il feedback.", "", "Il titolo dipende da mostraPasso(), che qui non presenta difetti visibili.", "L’accessibilità del pulsante non dipende da questa funzione."]}, {"case": "Dopo la prova con i colleghi vuoi migliorare i feedback. Quale richiesta all’IA è più mirata?", "options": ["Migliora tutti i feedback della lezione rendendoli più chiari, completi ed efficaci.", "Nell’esercizio 3, per la risposta 3/7, mostra l’indizio sul denominatore comune; il resto non cambia.", "Riscrivi la lezione tenendo conto dei commenti dei colleghi, che ti incollo qui di seguito.", "Rendi i feedback più personali, chiedendo il nome allo studente all’inizio e usandolo in ogni messaggio."], "correct": 1, "feedback": "Una modifica circoscritta, legata a un errore osservato e con ciò che deve restare invariato.", "hint": "Quale richiesta permette di verificare con un solo caso che la modifica funziona?", "why": ["«Tutti» e «più efficaci» lasciano al modello ogni decisione e rendono difficile la verifica.", "", "Riscrivere tutto rimette in discussione anche ciò che era già stato verificato.", "Raccoglie un dato personale senza necessità e non migliora il contenuto del feedback."]}], "id": 2, "version": 3, "concepts": [{"title": "Dal contenuto all’attività", "text": "Un contenuto espone informazioni; un’attività chiede una decisione o una produzione osservabile. Prima di aggiungere pulsanti, specifica che cosa farà lo studente e quale evidenza mostrerà la comprensione."}, {"title": "Il prompt come specifica", "text": "Una buona richiesta contiene destinatari, prerequisiti, obiettivo, azioni, feedback e criteri di accettazione. Scrivere questi elementi chiarisce la progettazione. Il prompt può essere rivisto dopo una prova."}, {"title": "Feedback e autonomia", "text": "Un indizio deve aiutare a riprendere il ragionamento. Prevedi sostegni iniziali e una prova finale con meno aiuti. Per risposte interpretative usa criteri espliciti e revisione umana, evitando una correzione automatica basata solo su parole chiave."}], "disciplineExamples": [{"area": "Italiano", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere tesi, argomento ed esempio in un testo breve fornito dal docente", "features": "Spiegazione, testo annotato, selezione di segmenti e feedback guidato", "evidence": "Individua una tesi in un testo nuovo e giustifica il confine del segmento.", "case": {"probe": "Testo: «La biblioteca di quartiere dovrebbe restare aperta la sera. Molti studenti lavorano di giorno e non hanno altro momento per studiare. Marta, per esempio, ci va dopo il turno al bar». Individua tesi, argomento ed esempio.", "full": "«Tesi: la prima frase. Argomento: molti studenti lavorano di giorno, ed è la ragione che sostiene la tesi. Esempio: il caso di Marta, che illustra l’argomento ma da solo non lo dimostra.»", "partial": "«La tesi è che Marta va in biblioteca dopo il turno.»", "why": "Scambia l’esempio, più concreto e facile da ricordare, per la tesi: non distingue il caso particolare dall’affermazione generale."}}, {"area": "Storia e filosofia", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere una tesi dalle ragioni che la sostengono", "features": "Esempio annotato, decisione, suggerimento e breve giustificazione", "evidence": "Ricostruisci tesi e ragione di un argomento nuovo.", "case": {"probe": "«Dovremmo dubitare delle nostre opinioni, perché molte convinzioni che sembravano certe si sono rivelate false». Ricostruisci tesi e ragione.", "full": "«Tesi: dovremmo dubitare delle nostre opinioni. Ragione: molte convinzioni ritenute certe si sono rivelate false. Il “perché” segnala il passaggio dalla tesi alla ragione.»", "partial": "«La tesi è che le nostre convinzioni sono false.»", "why": "Prende la ragione per la tesi e la generalizza: «molte si sono rivelate false» diventa «sono false»."}}, {"area": "Lingue straniere", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Formulare richieste cortesi in un dialogo B1", "features": "Esempio, scelta guidata, riformulazione e feedback con alternative ammissibili", "evidence": "Riformula una richiesta nuova in modo adeguato al contesto.", "case": {"probe": "Sei all’ufficio informazioni di una stazione a Londra e vuoi una mappa della città. Formula la richiesta.", "full": "«Could I have a map of the city, please?» oppure «Would you mind giving me a map?»: domanda con un modale e formula di cortesia, adatta a uno sconosciuto.", "partial": "«Give me a map, please.»", "why": "È corretta grammaticalmente, ma l’imperativo resta brusco anche con please: il registro non è adatto al contesto."}}, {"area": "Matematica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Sommare due frazioni con denominatori diversi", "features": "Esempio svolto, passaggi progressivi, esercizio e indizio", "evidence": "Risolvi una somma nuova senza l’esempio svolto.", "case": {"probe": "Calcola 2/3 + 1/4 senza guardare l’esempio svolto.", "full": "«Il minimo comune multiplo è 12: 8/12 + 3/12 = 11/12.»", "partial": "«3/7.»", "why": "Somma numeratori e denominatori tra loro: è l’errore che l’esercizio guidato doveva prevenire."}}, {"area": "Scienze e fisica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Leggere variabili e controlli in un esperimento semplice", "features": "Scenario, esempio, identificazione delle variabili e feedback", "evidence": "Indica variabile indipendente e controllo in un esperimento nuovo.", "case": {"probe": "Uno studente misura in quanto tempo si scioglie lo zucchero in acqua a 20, 40 e 60 °C, usando sempre 10 g di zucchero e 200 ml d’acqua, senza mescolare. Indica variabili e controlli.", "full": "«Variabile indipendente: la temperatura, perché è quella che cambio. Dipendente: il tempo di scioglimento. Controllate: massa di zucchero, volume d’acqua, nessun mescolamento.»", "partial": "«La variabile indipendente è il tempo, perché lo misura.»", "why": "Confonde la variabile misurata con quella modificata dallo sperimentatore."}}, {"area": "Arte e musica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Analizzare composizione, ritmo o struttura con una griglia", "features": "Esempio annotato, osservazione guidata e breve analisi personale", "evidence": "Applica la griglia a un’opera o brano diverso con materiali utilizzabili.", "case": {"probe": "Applica la griglia al tema dell’«Inno alla gioia» dal finale della Nona sinfonia di Beethoven, nella versione semplice per flauto: quante frasi, quali si ripetono?", "full": "«Quattro frasi della stessa lunghezza: A, A′ (come A ma con finale conclusivo), B (contrastante), A′. Lo ricavo dalle ripetizioni della melodia e dalle conclusioni delle frasi.»", "partial": "«È un brano ripetitivo e allegro.»", "why": "È un’impressione generale: la griglia chiede elementi osservabili come frasi, ripetizioni e contrasti."}}, {"area": "Informatica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Seguire l’esecuzione di una selezione condizionale", "features": "Traccia guidata, esempio e casi di confine", "evidence": "Spiega quale ramo viene eseguito per un input nuovo.", "case": {"probe": "if voto >= 6:\n    print(\"sufficiente\")\nelse:\n    print(\"insufficiente\")\nQuale ramo viene eseguito con voto = 6?", "full": "«Il primo: 6 >= 6 è vero, quindi stampa “sufficiente”. È proprio il caso di confine.»", "partial": "«Il secondo, perché 6 non è maggiore di 6.»", "why": "Legge >= come >: è l’errore tipico sui casi di confine, che la traccia guidata doveva far emergere."}}, {"area": "Diritto ed economia", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere i requisiti essenziali del contratto: accordo, causa, oggetto, forma quando prescritta", "features": "Esempio annotato di compravendita, decisione su un caso, indizio e breve giustificazione", "evidence": "Individua il requisito mancante in un contratto nuovo descritto dal docente.", "case": {"probe": "Luca e Sara firmano un foglio: «Luca vende a Sara un veicolo». Non è indicato quale veicolo, né un criterio per individuarlo. Quale requisito manca?", "full": "«Manca un oggetto determinato o determinabile (art. 1346 c.c.): non si sa quale bene passi da Luca a Sara. L’accordo c’è, ma senza uno dei requisiti dell’art. 1325 il contratto è nullo.»", "partial": "«Manca la forma, perché il contratto è scritto male.»", "why": "Confonde la forma, richiesta solo in alcuni casi, con la completezza del contenuto: non applica i requisiti uno per uno."}}, {"area": "Disegno e storia dell’arte", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Costruire le proiezioni ortogonali di un solido semplice", "features": "Esempio guidato su un prisma, passaggi progressivi (pianta, prospetto, profilo), esercizio e indizio", "evidence": "Disegna le tre viste di un solido nuovo e giustifica le linee nascoste.", "case": {"probe": "Un parallelepipedo ha un foro cilindrico verticale passante al centro. Che cosa compare nel prospetto frontale?", "full": "«Il rettangolo del parallelepipedo e due linee tratteggiate verticali: sono i contorni del foro, nascosti alla vista frontale. Il cerchio compare invece in pianta.»", "partial": "«Un cerchio al centro del rettangolo.»", "why": "Confonde le viste: il foro verticale si vede come cerchio dall’alto, mentre di fronte è nascosto e si rappresenta tratteggiato."}}], "promptContrast": {"weak": "Crea una lezione interattiva.", "reason": "Non è specificato cosa deve fare lo studente né quale feedback riceverà."}, "schedule": "15 min · ripresa: che cosa ha funzionato nel quiz in classe o in simulazione · 30 min · dal contenuto all’attività: progettare feedback e indizi · 80 min · laboratorio: lezione interattiva in quattro passaggi · 10 min pausa · 35 min · revisione dei feedback tra colleghi di discipline diverse · 30 min · attività in classe (modalità A+B) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "A+B", "modeLabel": "Modalità A+B · La classe usa e poi valuta", "title": "Riscrivere un feedback che non aiuta", "intro": "Gli studenti seguono la lezione interattiva che hai verificato, poi diventano revisori del feedback. Così il vibe coding entra in classe come oggetto di analisi, non solo come strumento.", "steps": [["5 min · Previsione", "Mostra il primo esercizio e chiedi quale errore commetterebbe un compagno distratto."], ["10 min · Percorso", "Gli studenti completano i quattro passaggi annotando quale indizio li ha davvero aiutati."], ["10 min · Revisione", "Ogni gruppo sceglie un feedback poco utile e lo riscrive perché guidi il ragionamento senza dare la soluzione."], ["5 min · Confronto", "Raccogli le riscritture migliori: potrai usarle come nuovi requisiti nel prompt di revisione."]], "assess": "Valuta se il nuovo feedback individua il passaggio critico del ragionamento disciplinare."}}, {"title": "Costruire una simulazione guidata", "intro": "Progetta un’app che colleghi parametri e risultati. Esplicita il modello e le sue ipotesi, poi verifica formule, unità di misura e casi limite.", "product": "Un simulatore del moto uniforme con parametri, risultato e spiegazione.", "goals": ["Definire variabili, unità e intervalli validi.", "Separare modello matematico e interfaccia.", "Controllare risultati con calcoli indipendenti."], "example": {"kind": "Simulatore", "audience": "Studenti di seconda liceo", "goal": "Interpretare la relazione tra velocità, tempo e distanza nel moto uniforme", "features": "Velocità in m/s tra 0 e 30, tempo in secondi tra 0 e 120, distanza in metri, spiegazione della formula e validazione degli input"}, "steps": [{"title": "1. Esplicita il modello prima della grafica", "explain": "Nel moto uniforme con posizione iniziale zero usiamo s = v × t. Assumiamo velocità costante e consideriamo la distanza con velocità non negativa. Il modello non descrive accelerazioni.", "prompt": "Progetta una simulazione del moto uniforme per [destinatari]. Usa s = v × t, posizione iniziale zero, v non negativa e costante. Dichiara variabili, unità, ipotesi e limiti. Non scrivere ancora il codice.", "action": "Scrivi quali fenomeni il modello descrive e quali lascia fuori.", "check": "Non confondi una rappresentazione visiva con una validazione scientifica."}, {"title": "2. Definisci input e intervalli", "explain": "Un campo deve dichiarare unità e limiti. Un valore vuoto non equivale automaticamente a zero.", "prompt": "Prevedi v in m/s tra 0 e 30 e t in secondi tra 0 e 120. Consenti valori decimali. Rifiuta campi vuoti, testo e numeri fuori intervallo con un messaggio vicino al campo. Definisci quando aggiornare il risultato.", "action": "Prepara esempi validi e non validi per entrambi i parametri.", "check": "I limiti dell’interfaccia coincidono con quelli dichiarati nel modello."}, {"title": "3. Chiedi la prima applicazione", "explain": "Il risultato deve mostrare numero, unità e significato. Aggiungi un grafico solo se serve a comprendere la relazione.", "prompt": "Genera un unico file HTML con CSS e JavaScript per la specifica concordata. Mostra input etichettati, distanza in metri e sostituzione numerica nella formula. Non visualizzare un risultato nuovo se gli input non sono validi. Inserisci una nota sui limiti del modello.", "action": "Apri il simulatore e modifica un solo parametro alla volta.", "check": "Capisci che cosa cambia e perché senza leggere il codice."}, {"title": "4. Confronta con un risultato indipendente", "explain": "Non usare l’IA come unica fonte di verifica del proprio codice. Calcola casi semplici a mano.", "prompt": "Prepara test per v=5 m/s e t=12 s (atteso 60 m), v=0 e t=12 (atteso 0 m), v=30 e t=120 (atteso 3600 m), un campo vuoto e v=-1. Per ogni caso specifica esito atteso e motivazione.", "action": "Esegui i cinque test e annota eventuali differenze.", "check": "Il simulatore calcola i casi validi e rifiuta quelli non ammessi."}, {"title": "5. Migliora la comprensione del fenomeno", "explain": "Un controllo interattivo deve aiutare a interpretare, non solo muovere un oggetto.", "prompt": "Aggiungi una domanda di previsione: a tempo costante, cosa succede alla distanza se raddoppio la velocità entro l’intervallo valido? Mostra la spiegazione dopo la scelta. Mantieni formule e validazione esistenti.", "action": "Confronta v=5 e v=10 con t=12 e spiega il rapporto.", "check": "Ottieni 60 m e 120 m e sai motivare il raddoppio."}], "quiz": [{"case": "Il simulatore del moto mostra un’auto animata in modo molto realistico. Che cosa ti dice questo sulla correttezza del modello?", "options": ["Che il modello è affidabile, perché un’animazione fluida richiede calcoli precisi.", "Nulla: formula, unità, intervalli e ipotesi vanno controllati a parte.", "Che il modello è corretto almeno a basse velocità, dove l’animazione rallenta.", "Che il modello è corretto se l’IA ha usato una libreria grafica affidabile."], "correct": 1, "feedback": "Una bella animazione non dimostra che il modello descriva correttamente il fenomeno.", "hint": "Distingui ciò che si vede sullo schermo dal calcolo che lo produce.", "why": ["La fluidità dipende dalla grafica, non dalla correttezza della formula.", "", "La velocità dell’animazione non dice nulla sulla correttezza del calcolo.", "Una libreria grafica disegna bene anche valori calcolati in modo sbagliato."]}, {"case": "Quale descrizione del modello deve comparire nella pagina del simulatore?", "options": ["Simulatore realistico del movimento di un’auto su strada, con dati verosimili.", "s = v × t, con velocità costante e partenza da zero; non descrive accelerazioni.", "Modello fisico avanzato basato sulle leggi della cinematica classica, adatto a ogni situazione.", "Simulazione generata con l’IA e verificata automaticamente durante la creazione."], "correct": 1, "feedback": "Formula, ipotesi e limiti visibili permettono a studenti e colleghi di controllare il modello.", "hint": "Quale descrizione ti permette di sapere quando il modello smette di valere?", "why": ["«Realistico» è una promessa, non una descrizione del modello.", "", "Non dichiara né la formula né le ipotesi: non si può controllare.", "La verifica non è automatica e la frase non descrive il modello."]}, {"case": "Lo studente lascia vuoto il campo del tempo e preme Calcola. Che cosa deve fare l’app?", "options": ["Calcolare con t = 0 e mostrare 0 m, che in questo caso è un risultato corretto.", "Segnalare che il campo è vuoto e chiedere un valore, senza calcolare.", "Usare l’ultimo valore inserito, per non interrompere l’esplorazione.", "Inserire un valore di esempio e mostrarlo evidenziato nel campo."], "correct": 1, "feedback": "Un valore vuoto non equivale automaticamente a zero: va segnalato.", "hint": "Il campo vuoto significa davvero «zero secondi»?", "why": ["Trattare il vuoto come zero produce un risultato che lo studente non ha chiesto.", "", "Lo studente vede un risultato che non corrisponde a ciò che ha inserito.", "Un valore inventato può essere scambiato per un dato dello studente."]}, {"case": "Come verifichi che il simulatore calcola correttamente la distanza?", "options": ["Chiedi all’IA che l’ha scritto di rileggere il codice e confermare la formula.", "Fai controllare il codice da un secondo assistente IA diverso dal primo.", "Calcoli a mano casi semplici, come 10 m/s per 3 s = 30 m, e li confronti.", "Controlli che il grafico distanza-tempo sia una retta, come previsto."], "correct": 2, "feedback": "Un risultato calcolato in modo indipendente è il confronto più affidabile.", "hint": "Quale controllo non dipende da un modello linguistico?", "why": ["L’IA non dovrebbe essere l’unica fonte di verifica del proprio codice.", "Un secondo modello può confermare lo stesso errore: resta una verifica non indipendente.", "", "Una retta può avere la pendenza sbagliata: la forma è necessaria, ma non sufficiente."]}, {"case": "Come strutturi l’attività degli studenti con il simulatore?", "options": ["Esplorazione libera: muovono tutti i cursori come preferiscono finché non scoprono la relazione.", "Prima una previsione scritta, poi cambiano una sola variabile e spiegano il risultato.", "Leggono la teoria e poi controllano che il simulatore la confermi.", "Cambiano velocità e tempo insieme, per vedere più casi in meno tempo."], "correct": 1, "feedback": "Prevedere, modificare una variabile e spiegare dà valore didattico all’interazione.", "hint": "Che cosa ti serve per confrontare un’aspettativa con un’osservazione?", "why": ["Senza previsione non c’è confronto, e muovere tutto insieme confonde gli effetti.", "", "Lo studente verifica il simulatore, ma non ragiona su una previsione propria.", "Cambiando due variabili insieme non si capisce quale ha prodotto l’effetto."]}, {"case": "Il simulatore mostra il risultato «Distanza: 54». Che cosa manca?", "options": ["Nulla, se la consegna dell’esercizio dice già che si lavora in metri.", "L’unità di misura e una frase che leghi il numero alla situazione.", "Un grafico che mostri come varia la distanza nel tempo.", "Più cifre decimali, per rendere il risultato più preciso."], "correct": 1, "feedback": "Il risultato deve mostrare numero, unità e significato.", "hint": "Lo studente sa interpretare quel numero senza rileggere la consegna?", "why": ["Il risultato va interpretato da solo: l’unità è parte del risultato.", "", "Un grafico è utile solo se aiuta a capire, e non sostituisce unità e significato.", "Più decimali non risolvono la mancanza di unità e significato."]}, {"case": "Con v = 36 km/h e t = 10 s questo codice mostra 360 m. Qual è il problema?", "code": "const v = Number(campoVelocita.value); // km/h\nconst t = Number(campoTempo.value);    // secondi\nconst s = v * t;\nrisultato.textContent = s + ' m';", "options": ["Nessuno: 36 × 10 fa 360, il calcolo è corretto.", "Manca la conversione da km/h a m/s: il risultato corretto è 100 m.", "Il tempo andrebbe espresso in ore: il risultato corretto è quindi 360 km, non 360 m.", "È un problema di arrotondamento: servono due cifre decimali."], "correct": 1, "feedback": "36 km/h corrispondono a 10 m/s: 10 m/s × 10 s = 100 m. Le unità vanno rese coerenti prima del calcolo.", "hint": "Controlla le unità di misura indicate nei commenti del codice.", "why": ["Il prodotto numerico è giusto, ma moltiplica grandezze con unità incoerenti.", "", "Anche convertendo il tempo in ore il risultato sarebbe 0,1 km, non 360 km.", "L’errore è di unità di misura, non di arrotondamento."]}, {"case": "In uno scenario di Storia una scelta porta alla frase «la guerra sarebbe stata evitata». Come va presentata agli studenti?", "options": ["Come conseguenza certa, perché deriva dalle fonti fornite nel percorso.", "Come scenario possibile, dichiarando regole e interpretazioni su cui si basa.", "Come previsione calcolata dall’IA a partire da molti casi storici simili.", "Come conclusione da ricordare per la verifica finale sull’argomento."], "correct": 1, "feedback": "Le conseguenze di uno scenario dipendono da regole esplicitate: non hanno la certezza di una legge fisica.", "hint": "Quanto è certa una storia controfattuale?", "why": ["Le fonti documentano ciò che è accaduto, non ciò che sarebbe potuto accadere.", "", "Non è una previsione statistica, ed è attribuita a una fonte non verificabile.", "Presentarla come conclusione trasforma un’ipotesi in un fatto."]}, {"case": "Un collega vuole aggiungere un grafico al simulatore. Quando ha senso farlo?", "options": ["Sempre: un grafico rende il simulatore più professionale e coinvolgente per gli studenti.", "Quando aiuta a capire la relazione tra le variabili, non solo a decorare.", "Solo se l’IA riesce a generarlo senza librerie esterne.", "Mai: i grafici distraggono gli studenti dalla formula del modello."], "correct": 1, "feedback": "Ogni elemento dell’interfaccia deve servire a interpretare il fenomeno.", "hint": "Che cosa deve ottenere lo studente dal grafico?", "why": ["L’aspetto professionale non è un criterio didattico.", "", "È un vincolo tecnico, non un criterio per decidere se il grafico serve.", "Un grafico ben scelto aiuta a vedere la proporzionalità."]}, {"case": "Quale specifica degli input è più corretta per il simulatore del moto uniforme?", "options": ["Velocità e tempo: qualsiasi numero, positivo o negativo, per lasciare la massima libertà di esplorazione.", "Velocità da 0 a 50 m/s e tempo da 0 a 600 s; valori vuoti o fuori intervallo segnalati.", "Velocità e tempo positivi; l’app corregge da sola i valori fuori intervallo.", "Velocità fino a 300 km/h e tempo in minuti, per avvicinarsi ai casi reali."], "correct": 1, "feedback": "Unità, intervalli e gestione degli input non validi sono dichiarati e verificabili.", "hint": "Quale specifica dice anche che cosa succede con un valore non ammesso?", "why": ["Numeri negativi o enormi producono risultati privi di senso nel modello.", "", "Una correzione silenziosa mostra un risultato diverso da ciò che lo studente ha inserito.", "Mescolare km/h e minuti senza conversioni dichiarate introduce errori di unità."]}], "id": 3, "version": 3, "concepts": [{"title": "Una simulazione rappresenta un modello", "text": "Un simulatore rende esplorabili relazioni dichiarate tra variabili. Formula, unità, intervalli e ipotesi devono essere visibili. Una bella animazione non dimostra che il modello descriva correttamente il fenomeno."}, {"title": "Prevedi, modifica, spiega", "text": "Prima di muovere un controllo fai formulare una previsione, poi cambia una sola variabile e chiedi una spiegazione del risultato. Il confronto tra previsione e osservazione dà valore didattico all’interazione."}, {"title": "Adatta il significato di scenario", "text": "In matematica e scienze puoi verificare risultati con calcoli noti. In un dialogo linguistico o in un caso storico, le conseguenze dipendono da regole e interpretazioni esplicitate: presentale come scelte di scenario, senza attribuire loro la certezza di una legge fisica."}], "disciplineExamples": [{"area": "Italiano", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Valutare l’effetto di connettivi diversi sulla coerenza di un paragrafo", "features": "Scelte tra connettivi, conseguenze testuali dichiarate e confronto fra versioni", "evidence": "Spiega come cambia il rapporto logico tra due frasi.", "case": {"probe": "«Ha studiato molto, ___ non ha superato la verifica». Confronta «quindi» ed «eppure».", "full": "«Eppure crea un rapporto di opposizione: il risultato contraddice ciò che ci si aspetterebbe. Quindi introdurrebbe una conseguenza e renderebbe la frase incoerente.»", "partial": "«Eppure suona meglio.»", "why": "La scelta è giusta, ma motivata dall’orecchio e non dal rapporto logico tra le due frasi."}}, {"area": "Storia e filosofia", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Confrontare due interpretazioni di una decisione storica usando le fonti fornite", "features": "Bivi con ipotesi esplicite, fonti e conseguenze presentate come scenari possibili", "evidence": "Argomenta quale fonte sostiene la tua scelta e quali limiti restano.", "case": {"probe": "Nello scenario scegli: «La decisione fu dettata soprattutto da ragioni economiche». Hai due fonti: il verbale della riunione in cui fu presa e un’intervista rilasciata vent’anni dopo da uno dei protagonisti.", "full": "«Il verbale sostiene meglio la scelta, perché registra le ragioni discusse in quel momento; l’intervista può risentire del senno di poi o del bisogno di difendersi. Limite: un verbale riporta ciò che si è detto, non tutte le motivazioni.»", "partial": "«L’intervista, perché lui c’era e lo spiega meglio.»", "why": "Valuta l’autorevolezza del testimone ma non la distanza nel tempo né lo scopo della fonte, e non indica alcun limite."}}, {"area": "Lingue straniere", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Scegliere un registro linguistico adatto all’interlocutore", "features": "Dialogo a bivi con battute predisposte, contesto e conseguenze comunicative", "evidence": "Motiva una scelta di registro e proponi un’alternativa.", "case": {"probe": "Scrivi al dirigente di una scuola straniera per avere informazioni su uno scambio. Scegli tra «Hi! Can you tell me about the exchange?» e «Dear Sir or Madam, I am writing to ask for information about the exchange programme».", "full": "«La seconda: l’interlocutore è sconosciuto e ha un ruolo istituzionale, quindi serve un registro formale, con formula d’apertura e forme complete. Un’alternativa ammissibile: “Dear Principal, I would like to ask…”.»", "partial": "«La seconda, perché è più lunga.»", "why": "La scelta è corretta, ma il criterio no: la lunghezza non decide il registro."}}, {"area": "Matematica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare come coefficiente angolare e intercetta modificano una retta", "features": "Input di m e q, grafico di y=mx+q, intervalli e casi noti", "evidence": "Prevedi il cambiamento del grafico prima di muovere un parametro.", "case": {"probe": "Retta y = 2x + 1. Prevedi che cosa succede se porti m da 2 a −2, lasciando q = 1.", "full": "«Passa ancora per (0; 1), perché q non cambia, ma diventa decrescente con la stessa inclinazione: è la simmetrica rispetto all’asse y.»", "partial": "«La retta si sposta più in basso.»", "why": "Confonde l’effetto di m, che cambia l’inclinazione, con quello di q, che sposta la retta in verticale."}}, {"area": "Scienze e fisica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Interpretare la relazione tra velocità costante, tempo e distanza", "features": "s=v×t, unità, intervalli ammessi e confronto con casi noti", "evidence": "Prevedi l’effetto di una variazione e controlla le unità del risultato.", "case": {"probe": "Un’auto procede a 15 m/s costanti. Che cosa succede alla distanza percorsa se il tempo passa da 4 s a 8 s?", "full": "«Raddoppia, da 60 m a 120 m: con velocità costante la distanza è direttamente proporzionale al tempo (s = v × t; m/s × s = m).»", "partial": "«Diventa 120.»", "why": "Il numero è giusto, ma mancano unità di misura e relazione di proporzionalità: non c’è prova che sappia prevedere un caso diverso."}}, {"area": "Arte e musica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare la relazione tra battiti al minuto e intervallo tra impulsi", "features": "Tempo in BPM, intervallo 60/BPM secondi, limiti positivi e spiegazione", "evidence": "Prevedi come cambia l’intervallo raddoppiando i BPM.", "case": {"probe": "Il metronomo passa da 80 a 160 BPM. Come cambia l’intervallo tra due impulsi?", "full": "«Si dimezza: da 60/80 = 0,75 s a 60/160 = 0,375 s. BPM e intervallo sono inversamente proporzionali.»", "partial": "«Raddoppia anche l’intervallo.»", "why": "Applica una proporzionalità diretta dove la relazione è inversa: più battiti al minuto significano impulsi più ravvicinati."}}, {"area": "Informatica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Osservare l’evoluzione di una variabile in un ciclo semplice", "features": "Stato passo passo, condizione, limite iterazioni e arresto", "evidence": "Prevedi valore finale e numero di iterazioni prima dell’esecuzione.", "case": {"probe": "x = 1\nwhile x < 20:\n    x = x * 3\nPrevedi valore finale e numero di iterazioni.", "full": "«x vale 27 dopo 3 iterazioni (1 → 3 → 9 → 27): il ciclo si ferma quando la condizione 27 < 20 risulta falsa.»", "partial": "«x vale 9, perché 27 supera 20.»", "why": "Pensa che il ciclo impedisca di superare il limite: la condizione si controlla prima di ogni iterazione, non dopo."}}, {"area": "Diritto ed economia", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare come prezzo e quantità di equilibrio cambiano quando si sposta la domanda o l’offerta", "features": "Curve lineari con parametri dichiarati, una curva spostata per volta, ipotesi del modello visibili", "evidence": "Prevedi la direzione di prezzo e quantità prima di spostare una curva.", "case": {"probe": "Il reddito dei consumatori aumenta e il bene è un bene normale. Prevedi prezzo e quantità prima di spostare la curva.", "full": "«La domanda si sposta a destra: a parità di offerta crescono sia il prezzo sia la quantità di equilibrio. Vale nel modello, con le altre condizioni invariate.»", "partial": "«Il prezzo sale, quindi la gente compra meno.»", "why": "Confonde lo spostamento della curva di domanda con un movimento lungo la curva: in questo caso la quantità scambiata aumenta."}}, {"area": "Disegno e storia dell’arte", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare come la posizione dell’osservatore modifica una prospettiva centrale", "features": "Altezza dell’orizzonte e distanza dal quadro modificabili, punto di fuga visibile, ipotesi dichiarate", "evidence": "Prevedi come cambia l’immagine abbassando la linea d’orizzonte, prima di muovere il cursore.", "case": {"probe": "Abbassi la linea d’orizzonte dall’altezza degli occhi di una persona in piedi fino al livello del pavimento. Che cosa succede a un cubo appoggiato a terra?", "full": "«Orizzonte e punto di fuga scendono a terra: la faccia superiore del cubo non si vede più, perché ora sta sopra l’altezza degli occhi, e il cubo appare visto dal basso, più imponente.»", "partial": "«Il cubo diventa più piccolo.»", "why": "Confonde l’altezza del punto di vista con la distanza dal quadro: abbassare l’orizzonte cambia l’angolo di veduta, non la grandezza apparente."}}], "promptContrast": {"weak": "Fai una simulazione realistica.", "reason": "Il modello, le variabili e i criteri di verifica sono lasciati impliciti."}, "schedule": "15 min · ripresa · 35 min · che cos’è un modello e quali ipotesi contiene · 80 min · laboratorio: simulazione o scenario della propria disciplina · 10 min pausa · 40 min · controllo dei risultati con calcoli o fonti indipendenti · 30 min · attività «prevedi, osserva, spiega» (modalità B) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "B", "modeLabel": "Modalità B · La classe verifica il modello", "title": "Prevedi, osserva, spiega e metti alla prova", "intro": "La simulazione diventa un oggetto da interrogare. Gli studenti confrontano le previsioni con il comportamento dell’app e controllano il modello con un calcolo o una fonte indipendente.", "steps": [["5 min · Previsione", "Prima di muovere un controllo ogni studente scrive che cosa succederà e perché."], ["10 min · Osservazione", "Le coppie cambiano una sola variabile per volta e registrano risultato e unità di misura o conseguenze dello scenario."], ["10 min · Controllo", "Ogni coppia verifica un risultato a mano o con una fonte e cerca un caso in cui il modello smette di valere."], ["5 min · Spiegazione", "Raccogli i limiti trovati: quali ipotesi del modello andrebbero dichiarate meglio?"]], "assess": "Valuta il confronto tra previsione e osservazione e la capacità di individuare i limiti del modello."}}, {"title": "Realizzare e correggere un sito web", "intro": "Costruisci un piccolo sito per un progetto scolastico. Definisci pagine, navigazione e contenuti, poi riproduci gli errori e chiedi correzioni circoscritte.", "product": "Un sito statico con tre pagine, navigazione coerente e registro dei test.", "goals": ["Scrivere una specifica di pagine e collegamenti.", "Descrivere un errore in modo riproducibile.", "Verificare navigazione, tastiera e dispositivi diversi."], "example": {"kind": "Sito web statico", "audience": "Visitatori di un progetto scolastico", "goal": "Trovare obiettivi, attività e risorse del progetto", "features": "Tre pagine: presentazione, attività e risorse; menu coerente, collegamenti relativi, layout mobile, nessun modulo che raccolga dati"}, "steps": [{"title": "1. Disegna la mappa del sito", "explain": "Un sito di tre pagine ha bisogno di collegamenti coerenti. Dai un nome ai file e definisci dove deve portare ogni voce di menu.", "prompt": "Progetta un sito statico per [progetto] rivolto a [pubblico]. Usa index.html, attivita.html e risorse.html nella stessa cartella. Definisci contenuto di ogni pagina, menu comune e tre compiti che un visitatore deve riuscire a svolgere. Non scrivere ancora codice.", "action": "Disegna le tre pagine e i collegamenti di andata e ritorno.", "check": "Da ogni pagina puoi raggiungere le altre due senza usare il tasto Indietro del browser."}, {"title": "2. Genera i file con vincoli espliciti", "explain": "Chiedi file distinti con nomi concordati. Un pulsante che promette di inviare messaggi richiede una funzione reale; in questa versione mantieni solo navigazione e contenuti statici.", "prompt": "Genera i tre file HTML concordati con CSS condiviso in stile.css. Usa collegamenti relativi e menu identico con pagina corrente evidenziata. Inserisci contenuti segnaposto riconoscibili, nessun dato personale o credenziale. Non simulare invii o salvataggi che non esistono. Spiega dove salvare i file.", "action": "Salva i quattro file nella stessa cartella e apri index.html.", "check": "I nomi nel menu corrispondono esattamente ai nomi dei file."}, {"title": "3. Prova come un visitatore", "explain": "Verifica ciò che una persona deve fare: raggiungere attività, tornare alla presentazione e aprire una risorsa. Prova anche senza mouse.", "prompt": "Prepara una checklist di collaudo per il sito: tutti i link interni da ogni pagina, risorse esterne, ordine di tabulazione, focus visibile, leggibilità a 390 pixel e titoli coerenti. Indica risultato atteso per ogni prova.", "action": "Segui tutti i collegamenti e annota pagina, azione ed esito.", "check": "Nessun contenuto essenziale richiede uno scorrimento orizzontale sul telefono."}, {"title": "4. Descrivi il difetto prima della correzione", "explain": "«Non funziona» non identifica una causa. Fornisci file, passaggi, risultato atteso e risultato osservato.", "prompt": "Nel file [nome], cliccando [link] dopo [passaggi] ottengo [osservato], mentre mi aspetto [atteso]. Ecco il codice pertinente: [codice]. Individua la causa e proponi la modifica minima. Non riscrivere il sito e non cambiare i nomi dei file senza necessità.", "action": "Introduci una correzione alla volta e ripeti la prova che falliva.", "check": "Il difetto è riproducibile prima e risolto dopo la modifica."}, {"title": "5. Ripeti i test e prepara la pubblicazione", "explain": "Una correzione al menu condiviso può influire su tutte le pagine. Per un sito statico puoi pianificare una pubblicazione su un hosting per file statici.", "prompt": "Elenca i test di regressione dopo la correzione. Verifica anche maiuscole e minuscole nei nomi e nei link. Descrivi una procedura di pubblicazione statica senza dichiararla eseguita. Elenca ciò che richiederebbe invece un servizio server.", "action": "Riprova il menu da tutte le pagine. Registra ciò che hai effettivamente controllato.", "check": "Distingui sito statico, funzione simulata e servizio operativo."}], "quiz": [{"case": "Nel sito statico del progetto vuoi un modulo «Invia la tua domanda al docente». Che cosa devi sapere prima di chiederlo all’IA?", "options": ["Che basta un pulsante Invia: il browser recapita il messaggio all’indirizzo indicato.", "Che serve un servizio esterno per ricevere i messaggi; altrimenti va tolto o sostituito.", "Che il messaggio resta salvato nel file HTML e il docente lo legge aprendo il file.", "Che il servizio di pubblicazione del sito inoltra da solo i moduli all’account del proprietario."], "correct": 1, "feedback": "Un sito statico mostra contenuti nel browser: ricevere messaggi richiede un servizio aggiuntivo, con le sue verifiche di privacy.", "hint": "Chiediti dove andrebbe a finire il messaggio, fisicamente.", "why": ["Il browser non spedisce messaggi da solo: serve un servizio che li riceva.", "", "Il file HTML non si modifica quando qualcuno compila un modulo.", "Un hosting per file statici serve pagine, non raccoglie moduli in modo automatico."]}, {"case": "Nel prototipo, premendo Invia compare «Messaggio inviato!». Che cosa dimostra questa scritta?", "options": ["Che il messaggio è arrivato, perché la conferma la mostra il sito stesso.", "Solo che la pagina mostra un testo: va verificato che un servizio l’abbia ricevuto.", "Che il messaggio è stato salvato nel browser e partirà alla prossima connessione.", "Che l’invio è riuscito, a meno che compaia un errore nella console del browser."], "correct": 1, "feedback": "Un messaggio sullo schermo non prova che una comunicazione sia stata recapitata.", "hint": "Chi ha scritto quella frase, e che cosa la fa comparire?", "why": ["La conferma è un testo generato dalla pagina: può comparire anche se nulla è stato inviato.", "", "Nulla nel prototipo indica un salvataggio o un invio differito.", "L’assenza di errori non dimostra che un invio sia avvenuto."]}, {"case": "Il menu non porta alla pagina Risorse. Quale descrizione permette all’IA una correzione mirata?", "options": ["Il menu non funziona più come dovrebbe: puoi controllarlo e correggerlo, per favore?", "Il sito ha problemi di navigazione: ricontrolla tutti i collegamenti e sistemali.", "Da index.html, clic su «Risorse»: atteso risorse.html, osservato errore 404.", "La pagina Risorse non si apre: rigenera il sito completo con il prompt iniziale."], "correct": 2, "feedback": "Passaggi, risultato atteso e risultato osservato rendono il difetto riproducibile.", "hint": "Quale descrizione permette a chiunque di riprodurre il difetto?", "why": ["«Non funziona» non identifica né il caso né la causa.", "Una richiesta generica autorizza modifiche ovunque, anche dove tutto funzionava.", "", "Rigenerare tutto può introdurre nuovi difetti e perde le parti già verificate."]}, {"case": "L’IA corregge il collegamento e, «per pulizia», riorganizza anche tutto il foglio di stile. Che cosa fai?", "options": ["Accetti: un foglio di stile più ordinato renderà più facili le modifiche future.", "Chiedi solo la correzione del collegamento e riprovi lo stesso caso che falliva.", "Accetti, ma ricontrolli soltanto la pagina Risorse che era stata appena corretta.", "Rifiuti, e da qui in avanti modifichi il codice del sito solo a mano."], "correct": 1, "feedback": "La modifica minima permette di capire che cosa è cambiato: ogni correzione è un’ipotesi da verificare.", "hint": "Se dopo la correzione qualcosa si rompe, sapresti dire perché?", "why": ["Modifiche non richieste allargano l’area da ritestare e nascondono la causa di nuovi difetti.", "", "Un foglio di stile riorganizzato riguarda tutte le pagine, non solo Risorse.", "Non serve rinunciare all’IA: serve circoscrivere la richiesta."]}, {"case": "Stai per applicare una correzione al menu condiviso dalle tre pagine. Che cosa fai prima?", "options": ["Niente: se la correzione non funziona, basta chiederla di nuovo all’IA.", "Conservi la versione funzionante, per poter confrontare e tornare indietro.", "Avvisi gli studenti che il sito sarà in manutenzione per qualche giorno.", "Pubblichi subito la correzione, così raccogli segnalazioni dagli utenti reali."], "correct": 1, "feedback": "Conservare la versione precedente rende reversibile ogni tentativo di correzione.", "hint": "Che cosa ti serve se la correzione peggiora le cose?", "why": ["Una nuova richiesta non riporta il sito allo stato di prima.", "", "Non protegge la versione che funzionava.", "Usare gli studenti come collaudatori di una correzione non provata li espone ai difetti."]}, {"case": "Hai corretto il menu condiviso da tutte e tre le pagine. Quali prove ripeti?", "options": ["Solo il collegamento corretto, perché il resto del menu non è stato modificato.", "La navigazione da tutte e tre le pagine, compresi i collegamenti che già funzionavano.", "Solo la pagina iniziale, da cui parte ogni visitatore che arriva al sito.", "Nessuna, se l’IA ha indicato con precisione tutte le parti che ha modificato."], "correct": 1, "feedback": "Una correzione a un elemento condiviso può influire su tutte le pagine: si ripetono le prove su ciascuna.", "hint": "Il menu è uno solo, ma in quante pagine compare?", "why": ["Il menu è condiviso: una modifica può rompere voci che prima funzionavano.", "", "I visitatori arrivano anche alle altre pagine, dove il menu deve funzionare.", "L’elenco delle modifiche dichiarate non sostituisce le prove."]}, {"case": "Come verifichi che il sito sia usabile da tastiera?", "options": ["Chiedi all’IA di rileggere il codice e confermare che rispetta le linee guida di accessibilità.", "Usi solo Tab, Invio e frecce per raggiungere ogni voce e attività, controllando il focus.", "Controlli che tutti i pulsanti abbiano colori ben contrastati con lo sfondo.", "Apri il sito sullo smartphone: se funziona al tocco, funziona anche da tastiera."], "correct": 1, "feedback": "L’accessibilità si prova con azioni reali, oltre che con la revisione del codice.", "hint": "Prova a immaginare di non avere il mouse.", "why": ["Una conferma dell’IA non è una prova eseguita.", "", "Il contrasto è importante, ma non dice nulla sull’uso da tastiera.", "Tocco e tastiera sono modalità diverse: una voce può funzionare al tocco e non con Tab."]}, {"case": "Questa voce di menu funziona con il mouse. Quale problema ha?", "code": "<div class=\"voce\" onclick=\"location.href='attivita.html'\">\n  Attività\n</div>", "options": ["Nessuno: l’importante è che porti alla pagina corretta.", "Non si raggiunge né si attiva da tastiera: serve un collegamento <a href>.", "Il nome del file andrebbe scritto con l’iniziale maiuscola.", "Il problema è solo estetico: manca la sottolineatura dei collegamenti."], "correct": 1, "feedback": "Un <div> con onclick non riceve il focus: chi usa la tastiera non può raggiungerlo.", "hint": "Prova a raggiungere questa voce premendo solo Tab.", "why": ["Funziona con il mouse, ma esclude chi naviga da tastiera.", "", "Il nome del file non c’entra con il difetto.", "Il problema non è estetico: la voce non è raggiungibile da tastiera."]}, {"case": "Prima di chiedere il sito all’IA, che cosa definisci?", "options": ["La palette dei colori e il carattere tipografico del sito.", "Le pagine, i nomi dei file e dove porta ciascuna voce di menu.", "Il nome di dominio e il servizio di hosting a pagamento da acquistare per la pubblicazione.", "Il numero di visite atteso nel primo mese di pubblicazione."], "correct": 1, "feedback": "La mappa del sito rende coerenti i collegamenti e verificabile la navigazione.", "hint": "Che cosa ti serve per sapere se un collegamento è giusto?", "why": ["L’aspetto grafico viene dopo la struttura.", "", "Dominio e hosting non servono per progettare e provare il sito.", "Le visite previste non incidono sulla progettazione delle pagine."]}, {"case": "Il sito è stato provato. Come lo pubblichi restando coerente con la sua natura?", "options": ["Su un servizio di hosting per file statici, senza credenziali nel codice.", "Su un server con database, necessario per qualunque sito pubblico.", "Su una chiavetta da distribuire, perché online un sito statico non funziona.", "Nell’area riservata del registro, con la password della scuola nel codice."], "correct": 0, "feedback": "Un sito statico si pubblica su un hosting per file statici, senza dati sensibili o credenziali nel codice.", "hint": "Di che cosa ha bisogno, davvero, un sito fatto solo di pagine HTML?", "why": ["", "Un sito di sole pagine non ha bisogno di un database.", "I siti statici funzionano normalmente online.", "Una password nel codice è leggibile da chiunque apra la pagina."]}], "id": 4, "version": 3, "concepts": [{"title": "Che cosa fa un sito statico", "text": "Le pagine descrivono contenuti, collegamenti e interazioni nel browser. Un archivio condiviso o un accesso per account richiedono servizi aggiuntivi. Un messaggio «inviato» sullo schermo non prova che una comunicazione sia stata recapitata."}, {"title": "Debugging come indagine", "text": "Riproduci il difetto, scrivi atteso e osservato, formula un’ipotesi e applica una modifica minima. Conserva la versione precedente. Ogni correzione è un’ipotesi da verificare con lo stesso caso che falliva."}, {"title": "L’accessibilità è parte del compito", "text": "Chi usa tastiera, telefono o ingrandimento deve poter svolgere l’attività essenziale. Etichette chiare e focus visibile si provano con azioni reali, oltre alla revisione del codice."}], "disciplineExamples": [{"area": "Italiano", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un percorso di lettura con testi originali o autorizzati", "features": "Tre pagine: percorso, attività e risorse; crediti e navigazione", "evidence": "Un compagno trova un testo e raggiunge la relativa attività senza aiuto.", "case": {"probe": "Chiedi a un compagno: «Trova il racconto sul tema del viaggio e apri l’attività di scrittura collegata».", "full": "Il compagno raggiunge il testo dal menu «Percorso», segue il collegamento all’attività nella stessa pagina e la apre senza chiedere aiuto né tornare alla home.", "partial": "Il compagno trova il racconto, ma chiede dove sia l’attività o la cerca tornando alla home.", "why": "Il contenuto c’è, ma il collegamento tra testo e attività non è evidente: è un difetto di navigazione da correggere, non un errore del compagno."}}, {"area": "Storia e filosofia", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un dossier di fonti su un tema circoscritto", "features": "Tre pagine: quesito, fonti, confronto; provenienza dei documenti", "evidence": "Trova la fonte pertinente e spiega come risponde al quesito.", "case": {"probe": "Quesito del dossier: «Quali erano le condizioni di lavoro nelle fabbriche di fine Ottocento?». Il dossier contiene un regolamento di fabbrica del 1890 e un capitolo di manuale del 2010.", "full": "Lo studente apre il regolamento e spiega che risponde al quesito perché fissa orari, multe e divieti dell’epoca; ne indica la provenienza riportata nella pagina «Fonti».", "partial": "Lo studente sceglie il manuale «perché spiega tutto» e non dice da dove viene.", "why": "Trova un testo sul tema, ma non valuta come risponde al quesito né distingue la fonte dalla ricostruzione storiografica."}}, {"area": "Lingue straniere", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un itinerario linguistico con istruzioni accessibili", "features": "Tre pagine: situazione, attività, risorse; testi B1 validati", "evidence": "Un compagno raggiunge l’attività seguendo le istruzioni nella lingua studiata.", "case": {"probe": "Istruzioni in inglese: «Go to Activities, choose “At the station” and complete task 2».", "full": "Il compagno arriva all’attività seguendo solo le istruzioni in lingua e, se richiesto, spiega che cosa ha cercato e dove.", "partial": "Il compagno ci arriva cliccando a caso o dopo aver chiesto la traduzione.", "why": "La pagina è stata trovata, ma non grazie alla comprensione delle istruzioni, che era l’obiettivo."}}, {"area": "Matematica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare una piccola raccolta di problemi per argomento", "features": "Tre pagine: argomenti, problemi e metodi; notazione leggibile", "evidence": "Trova il metodo pertinente a un problema nuovo.", "case": {"probe": "Problema nuovo: «Un rettangolo ha perimetro 30 cm e un lato di 6 cm: quanto misura l’altro?». Trova nel sito il metodo pertinente.", "full": "Lo studente apre la sezione su perimetri e aree, sceglie la formula inversa del perimetro e spiega perché: conosce il perimetro e un lato e cerca l’altro (9 cm).", "partial": "Lo studente apre la pagina delle aree «perché c’è un rettangolo».", "why": "Riconosce la figura, ma non le grandezze note e quella cercata, che sono ciò che decide il metodo."}}, {"area": "Scienze e fisica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Presentare un’esperienza di laboratorio riproducibile", "features": "Tre pagine: domanda, procedura e risultati dimostrativi etichettati", "evidence": "Un compagno ricostruisce la procedura e distingue dati reali da dimostrativi.", "case": {"probe": "Esperienza: misura del periodo di un pendolo. La pagina «Risultati» contiene valori in parte etichettati come dimostrativi.", "full": "Il compagno elenca i passaggi nell’ordine corretto con materiali e misure, e indica quali valori sono dati reali e quali dimostrativi grazie all’etichetta.", "partial": "Il compagno ricostruisce la procedura, ma presenta i valori dimostrativi come risultati dell’esperimento.", "why": "La distinzione tra dati reali e dimostrativi non è stata colta: forse l’etichetta non è abbastanza visibile, e va corretta."}}, {"area": "Arte e musica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Curare una piccola mostra o un percorso di ascolto commentato", "features": "Tre pagine: tema, opere o brani, commenti; crediti e diritti dei materiali", "evidence": "Un visitatore collega un’opera al tema e ne motiva la scelta.", "case": {"probe": "Mostra sul tema «il paesaggio»: chiedi a un visitatore di scegliere un’opera e motivarla.", "full": "Il visitatore sceglie «Viandante sul mare di nebbia» di Caspar David Friedrich e motiva: il paesaggio occupa quasi tutta la scena e la figura di spalle invita a guardarlo, come spiega il commento.", "partial": "Il visitatore sceglie un’opera «perché è bella» o «perché c’è la natura».", "why": "La scelta non è collegata al tema del percorso né agli elementi indicati nei commenti."}}, {"area": "Informatica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Costruire una documentazione navigabile di un piccolo progetto", "features": "Tre pagine: obiettivo, uso e test; menu coerente", "evidence": "Un collega apre l’esempio e ripete una prova senza aiuto.", "case": {"probe": "Un collega apre la documentazione e deve ripetere il test «inserimento di un voto non valido».", "full": "Il collega trova il test nella pagina «Test», usa i dati indicati e ottiene il messaggio atteso, senza chiedere aiuto.", "partial": "Il collega trova la pagina ma chiede quale valore inserire, oppure ottiene un esito diverso e non sa se è un errore.", "why": "La documentazione è incompleta: mancano i dati di input o il risultato atteso."}}, {"area": "Diritto ed economia", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un percorso sui principi fondamentali della Costituzione", "features": "Tre pagine: principi, articoli citati dal testo ufficiale, casi da analizzare; fonte di ogni articolo", "evidence": "Collega un caso nuovo all’articolo pertinente e motiva il collegamento.", "case": {"probe": "Caso: un’azienda paga una lavoratrice meno dei colleghi uomini che svolgono le stesse mansioni. A quale articolo lo colleghi?", "full": "«All’art. 3 Cost., che vieta distinzioni di sesso, e, se il percorso lo riporta, all’art. 37, che garantisce alla donna lavoratrice la stessa retribuzione a parità di lavoro.»", "partial": "«All’art. 1, perché l’Italia è fondata sul lavoro.»", "why": "Si aggancia al tema generico, il lavoro, invece che al principio violato, l’uguaglianza."}}, {"area": "Disegno e storia dell’arte", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un percorso di lettura su un’architettura del territorio", "features": "Tre pagine: contesto, lettura guidata (pianta, elementi, materiali), fonti e licenze delle immagini", "evidence": "Un compagno trova la pianta e collega un elemento al periodo storico.", "case": {"probe": "Percorso sulla Reggia di Caserta di Luigi Vanvitelli, iniziata nel 1752: chiedi a un compagno di trovare la pianta e di collegare un elemento al periodo.", "full": "Il compagno apre «Lettura guidata», trova la pianta con i quattro cortili e collega l’impianto simmetrico e monumentale al tardo Barocco e alla rappresentazione del potere borbonico, come spiega la scheda.", "partial": "Il compagno trova la pianta, ma risponde: «È antica e molto grande».", "why": "Ha raggiunto la pagina, ma non collega elementi osservabili al periodo: forse il collegamento non è abbastanza esplicito nella pagina, o il compito non è chiaro."}}], "promptContrast": {"weak": "Crea un sito moderno.", "reason": "Mancano mappa, compiti del visitatore e limiti delle funzioni."}, "schedule": "15 min · ripresa · 30 min · sito statico e debugging come indagine · 75 min · laboratorio: sito in tre pagine e correzione di un difetto · 10 min pausa · 40 min · prove da tastiera, smartphone e ingrandimento tra colleghi · 30 min · progettare la specifica con gli studenti (modalità C guidata) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "C guidata", "modeLabel": "Modalità C guidata · La classe specifica, il docente genera", "title": "La specifica come compito di scrittura", "intro": "Gli studenti progettano senza usare direttamente l’IA: scrivono la mappa e i requisiti di un piccolo sito. Tu generi il prototipo dal loro testo, lo mostri e la classe verifica se rispetta la specifica.", "steps": [["5 min · Compito", "Presenta l’argomento del sito e chi lo visiterà."], ["10 min · Specifica", "I gruppi scrivono mappa, contenuto di ogni pagina e due verifiche osservabili."], ["10 min · Generazione e prova", "Generi in diretta una versione dalla specifica di un gruppo; la classe controlla collegamenti, contenuti e uso da tastiera."], ["5 min · Revisione", "Che cosa mancava nella specifica? Ogni gruppo aggiunge un requisito che avrebbe evitato il difetto."]], "assess": "Valuta chiarezza, completezza e verificabilità della specifica: è una competenza di scrittura e di argomentazione."}}, {"title": "Costruire la tua applicazione passo passo", "intro": "Scegli un’app utile: generatore di esercizi, test, lezione o altro strumento. Riduci l’idea a una versione minima e guida ogni iterazione con requisiti e prove.", "product": "Un prototipo personale accompagnato da specifica, prompt e registro delle modifiche.", "goals": ["Scegliere una funzione principale utile e fattibile.", "Pianificare iterazioni verificabili.", "Usare le prove di un’altra persona per migliorare il prodotto."], "example": {"kind": "Generatore di esercizi", "audience": "Studenti di prima liceo", "goal": "Esercitare somme tra frazioni con denominatori positivi", "features": "Generazione di un esercizio alla volta con valori piccoli, input numeratore e denominatore, verifica per equivalenza, suggerimento e nuovo esercizio"}, "steps": [{"title": "1. Scegli il bisogno e delimita la versione minima", "explain": "Puoi scegliere un quiz, una lezione, un sito, un generatore o uno strumento diverso. Per il primo rilascio scegli una sola azione centrale.", "prompt": "Voglio creare [tipo di app] per [utenti], per aiutarli a [obiettivo]. Aiutami a definire un prototipo minimo con tre funzioni indispensabili, funzioni escluse e criteri di accettazione. Non aggiungere account o servizi esterni se non sono necessari.", "action": "Scrivi una frase che descriva l’utilità del prototipo e tre funzioni essenziali.", "check": "La prima versione è realizzabile e ha un esito osservabile."}, {"title": "2. Chiarisci le regole del dominio", "explain": "Nel generatore di frazioni non basta confrontare il testo scritto dall’utente: 2/4 e 1/2 sono equivalenti. Rendi esplicite queste regole.", "prompt": "Per il generatore di somme di frazioni usa numeri piccoli e denominatori positivi. Accetta risposte equivalenti tramite confronto dei prodotti incrociati. Rifiuta denominatore zero e input non numerici. Definisci cinque esempi con esito atteso prima del codice.", "action": "Sostituisci le regole dell’esempio con quelle della tua disciplina se scegli un’altra app.", "check": "Sai motivare ogni criterio di correttezza senza affidarti soltanto all’IA."}, {"title": "3. Procedi per versioni", "explain": "Non richiedere tutte le estensioni insieme. Prima verifica il flusso essenziale, poi aggiungi un solo miglioramento.", "prompt": "Realizza la versione 1 in un file HTML: genera un esercizio, accetta la risposta e mostra l’esito. Rimanda statistiche, livelli e account. Spiega come provarla. Non dichiarare eseguiti test non effettuati.", "action": "Prova il flusso completo con un esercizio noto.", "check": "L’azione principale funziona prima di aggiungere funzioni accessorie."}, {"title": "4. Chiedi un miglioramento preciso", "explain": "Dopo una prova puoi aggiungere indizi, un livello o un’esportazione. Collega ogni modifica a un problema osservato.", "prompt": "Durante la prova ho osservato [problema]. Aggiungi [una funzione] mantenendo invariati [comportamenti]. Indica i file modificati e i test da ripetere. Non estendere l’ambito ad altre funzioni.", "action": "Conserva la versione precedente e confronta gli esiti degli stessi test.", "check": "Puoi ricondurre ogni modifica a una necessità concreta."}, {"title": "5. Fai provare e prepara la consegna", "explain": "Una persona che non conosce il progetto può individuare ostacoli che tu non noti. Raccogli osservazioni su compiti reali, non soltanto gradimento.", "prompt": "Prepara una scheda per far provare il prototipo a un’altra persona: tre compiti, risultati attesi, spazio per osservato e problemi. Poi aiutami a ordinare le correzioni per impatto sull’obiettivo. Non inventare risultati del test.", "action": "Fai eseguire i compiti, correggi un ostacolo importante e allega prompt, file e registro dei test.", "check": "La consegna include limiti noti e prove reali, non solo una descrizione positiva."}], "quiz": [{"case": "Il tuo progetto prevede generatore, statistiche, livelli, esportazione e classifica. Che cosa realizzi nella prima versione?", "options": ["Tutte le funzioni in forma semplificata, per avere subito un’idea completa del progetto.", "Solo il generatore con il controllo della risposta, e l’elenco di ciò che resta fuori.", "Le statistiche, perché danno al docente i dati per decidere come sviluppare il resto.", "Le funzioni che l’IA dichiara di poter realizzare insieme in un unico file."], "correct": 1, "feedback": "La versione minima realizza l’azione centrale; ciò che resta fuori va scritto, per non allargare il lavoro.", "hint": "Qual è l’azione senza la quale il progetto non ha senso?", "why": ["Cinque funzioni semplificate sono cinque funzioni da verificare, nessuna davvero pronta.", "", "Senza il generatore non ci sono dati da raccogliere.", "Il perimetro lo decide l’obiettivo didattico, non ciò che l’IA sa fare."]}, {"case": "In un generatore di frazioni la risposta corretta è «1/2». Lo studente scrive «2/4». Che cosa succede, e perché è un problema?", "code": "function controlla(risposta, corretta) {\n  return risposta.trim() === corretta;\n}", "options": ["Viene accettata, perché trim() confronta il valore numerico delle frazioni.", "Viene rifiutata: il confronto è tra testi, mentre 2/4 e 1/2 sono equivalenti.", "Viene rifiutata, ed è giusto: un generatore deve sempre confrontare il testo esatto.", "Produce un errore, perché la barra non è un carattere ammesso nel confronto."], "correct": 1, "feedback": "La regola del dominio va resa esplicita: qui serve confrontare le frazioni per equivalenza.", "hint": "Che cosa fa trim(), e che cosa confronta l’operatore ===?", "why": ["trim() toglie solo gli spazi: il confronto resta tra stringhe di testo.", "", "Il controllo deve seguire le regole della disciplina, non la forma del testo.", "La barra è un carattere come gli altri: il confronto avviene, ma tra testi."]}, {"case": "Che cosa dichiari nelle regole del dominio di un generatore di esercizi sui connettivi?", "options": ["Solo la risposta corretta per ogni frase, così il controllo automatico resta sempre univoco.", "Le risposte accettate, quelle non accettate e i casi da far valutare al docente.", "Che l’IA decida al momento quali alternative sono accettabili.", "Che ogni risposta diversa da quella prevista vale mezzo punto."], "correct": 1, "feedback": "Esempi accettati, non accettati e casi da valutare rendono esplicito il criterio disciplinare.", "hint": "Pensa a due connettivi diversi entrambi corretti nella stessa frase.", "why": ["Esclude alternative linguisticamente corrette, come «tuttavia» ed «eppure».", "", "Delega all’IA un criterio che deve decidere il docente.", "Il mezzo punto non distingue un’alternativa corretta da un errore."]}, {"case": "La prima versione funziona. Quale passo successivo segue il metodo del corso?", "options": ["Chiedere in un unico prompt livelli, indizi ed esportazione, così da risparmiare tempo prezioso.", "Aggiungere un solo miglioramento legato a un problema osservato, poi ripetere i test.", "Passare a un’altra app, perché la prima è già pronta per la classe.", "Chiedere all’IA quali funzioni aggiungere per rendere l’app più completa."], "correct": 1, "feedback": "Si procede per versioni: un miglioramento alla volta, motivato e verificato.", "hint": "Se dopo tre modifiche insieme qualcosa si rompe, sapresti quale l’ha causato?", "why": ["Più modifiche insieme rendono difficile capire quale abbia causato un difetto.", "", "Una versione che funziona tecnicamente non è ancora provata con altre persone.", "Le aggiunte devono rispondere a bisogni osservati, non a suggerimenti generici."]}, {"case": "Quale motivazione giustifica davvero l’aggiunta di un sistema di indizi?", "options": ["Le app educative più usate hanno quasi tutte un sistema di indizi.", "Nella prova, quattro colleghi su sei si sono bloccati allo stesso passaggio.", "L’IA ha suggerito che gli indizi aumentano molto il coinvolgimento degli studenti.", "Gli indizi sono facili da aggiungere e non richiedono nuovi test."], "correct": 1, "feedback": "Una funzione si aggiunge quando risponde a un bisogno osservato.", "hint": "Quale motivazione nasce da una prova reale?", "why": ["Ciò che fanno altre app non dice nulla sul bisogno della tua.", "", "Un suggerimento generico non è un’osservazione sul tuo prodotto.", "Ogni modifica richiede di ripetere i test."]}, {"case": "Un collega prova la tua app. Quale raccolta di osservazioni ti serve di più?", "options": ["Un voto da 1 a 10 sul gradimento complessivo e un breve commento libero.", "Che cosa ha cercato di fare, dove si è bloccato e che cosa si aspettava di vedere.", "Le sue proposte di funzioni nuove da aggiungere nella prossima versione.", "Se l’app gli sembra adatta, nel complesso, ai suoi studenti e alle classi in cui insegna."], "correct": 1, "feedback": "Le osservazioni su compiti reali mostrano gli ostacoli; il gradimento da solo non li rivela.", "hint": "Quale informazione ti dice che cosa correggere?", "why": ["Il gradimento non indica dove l’app crea difficoltà.", "", "Le nuove funzioni allargano il progetto prima di aver risolto i problemi.", "È un giudizio complessivo che non dice che cosa migliorare."]}, {"case": "Durante lo sviluppo un collega ti chiede di salvare i risultati degli studenti per classe. Che cosa fai?", "options": ["Lo aggiungi subito: è una richiesta ragionevole e molto utile.", "Lo annoti tra ciò che resta fuori: richiede dati personali e un’architettura diversa.", "Lo aggiungi salvando nel browser i risultati insieme al nome dello studente.", "Chiedi all’IA come gestire quei dati in modo sicuro e segui con attenzione le sue indicazioni."], "correct": 1, "feedback": "Ciò che resta fuori dall’ambito va scritto; i dati degli studenti richiedono valutazioni di privacy e architettura.", "hint": "Che cosa cambierebbe nel progetto, se dovesse conservare dati degli studenti?", "why": ["Allarga il perimetro e introduce dati personali senza valutazione.", "", "Il browser condiviso del laboratorio non è un luogo adatto ai dati degli studenti.", "Le scelte sui dati personali spettano alla scuola e al DPO, non all’assistente."]}, {"case": "Che cosa conservi durante lo sviluppo per rendere osservabile il tuo processo?", "options": ["Solo la versione finale del file, per non creare confusione tra copie.", "Il prompt iniziale, le revisioni, le versioni del file e i test con esito.", "La cronologia completa della chat, che contiene già tutte le informazioni utili.", "Uno screenshot dell’app per ogni versione prodotta."], "correct": 1, "feedback": "Prompt, versioni e test permettono di ricostruire e spiegare le scelte fatte.", "hint": "Che cosa serve per spiegare a un collega come sei arrivato al risultato?", "why": ["Senza le versioni precedenti non puoi confrontare né tornare indietro.", "", "La chat mescola tentativi e decisioni e non registra le prove eseguite.", "Uno screenshot mostra l’aspetto, non il comportamento verificato."]}, {"case": "Nel generatore di Arte lo studente motiva un’analisi con parole sue. Come gestisci la valutazione?", "options": ["Con un elenco di termini tecnici: se la motivazione ne contiene due, è corretta.", "Con una rubrica di criteri osservabili e la revisione finale del docente.", "Facendo valutare la risposta all’IA durante l’uso, in tempo reale.", "Accettando ogni motivazione, perché l’interpretazione di un’opera è libera."], "correct": 1, "feedback": "Per interpretazioni aperte servono criteri espliciti e la valutazione umana.", "hint": "Una buona analisi può non usare nessun termine tecnico previsto?", "why": ["Il lessico tecnico non garantisce un’analisi fondata su elementi osservabili.", "", "Invia testi degli studenti a un servizio esterno e delega il giudizio al modello.", "Un’interpretazione libera deve comunque poggiare su elementi visibili nell’opera."]}, {"case": "Quale richiesta di miglioramento è formulata correttamente?", "options": ["Rendi il generatore più intelligente e adattivo, come farebbe un’app professionale per la scuola.", "Aggiungi un livello 2 con denominatori fino a 12, senza toccare il livello 1; indica i test da ripetere.", "Aggiungi tutti i livelli di difficoltà che ritieni utili per gli studenti di un liceo scientifico italiano.", "Migliora il generatore nel modo che ritieni più efficace per la classe e per il docente."], "correct": 1, "feedback": "Un miglioramento preciso dichiara che cosa aggiungere, che cosa preservare e che cosa ritestare.", "hint": "Quale richiesta puoi verificare con un caso concreto?", "why": ["«Più intelligente» non è verificabile e lascia ogni decisione al modello.", "", "Delega all’IA il perimetro del progetto.", "Non indica che cosa cambiare né come verificarlo."]}], "id": 5, "version": 3, "concepts": [{"title": "Dal prototipo al progetto didattico", "text": "La versione minima realizza l’azione centrale del progetto. Una funzione si aggiunge quando risponde a un bisogno osservato. Scrivi ciò che resta fuori dall’ambito per evitare che ogni richiesta allarghi il lavoro."}, {"title": "Il contenuto disciplina la tecnologia", "text": "Le regole di verifica dipendono dalla disciplina: equivalenza tra frazioni, uso di un connettivo, attendibilità di una fonte. Dichiara esempi accettati, esempi non accettati e casi che richiedono valutazione umana."}, {"title": "Costruire è anche documentare", "text": "Conserva prompt iniziale, revisioni, versioni del file e test. Far spiegare una scelta o un errore rende osservabile il processo del corsista e, in seguito, quello degli studenti."}], "disciplineExamples": [{"area": "Italiano", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare l’uso di connettivi logici in frasi originali", "features": "Banca validata, completamento, suggerimento; alternative linguistiche ammissibili esplicitate", "evidence": "Motiva la scelta del connettivo e discuti un’alternativa plausibile.", "case": {"probe": "«Era stanco, ___ continuò a lavorare». Il generatore accetta «tuttavia». Motiva la scelta e discuti «eppure».", "full": "«Tuttavia esprime opposizione tra la stanchezza e il continuare; anche eppure è ammissibile con lo stesso valore. Perciò no: indicherebbe una conseguenza.»", "partial": "«Va bene solo tuttavia, perché è la risposta dell’app.»", "why": "Affida la correttezza all’app invece che al rapporto logico, ed esclude un’alternativa valida."}}, {"area": "Storia e filosofia", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Analizzare argomenti distinguendo premesse e conclusione", "features": "Casi originali controllati, campi per ricostruzione e criteri di revisione", "evidence": "Ricostruisci un argomento inedito con premesse e conclusione.", "case": {"probe": "«Chi legge molto amplia il proprio lessico. Giulia legge un libro a settimana. Quindi il suo lessico si sta ampliando». Ricostruisci l’argomento.", "full": "«Premesse: chi legge molto amplia il lessico; Giulia legge molto, un libro a settimana. Conclusione: il lessico di Giulia si sta ampliando, introdotta da “quindi”.»", "partial": "«Premessa: Giulia legge un libro a settimana. Conclusione: chi legge molto amplia il lessico.»", "why": "Scambia la premessa generale con la conclusione e non riconosce l’indicatore “quindi”."}}, {"area": "Lingue straniere", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Allenare lessico contestualizzato da una banca di esempi controllata", "features": "Frasi originali, indizi graduati e varianti accettate dichiarate", "evidence": "Usa una parola in una frase nuova pertinente.", "case": {"probe": "Usa «borrow» in una frase nuova.", "full": "«Can I borrow your dictionary until tomorrow?»: significato corretto (prendere in prestito) e contesto pertinente.", "partial": "«Can you borrow me your pen?»", "why": "Confonde borrow con lend: la frase è plausibile ma il significato è rovesciato, un errore tipico per chi pensa in italiano «prestare»."}}, {"area": "Matematica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare somme di frazioni accettando risposte equivalenti", "features": "Numeri piccoli, denominatori positivi e confronto per equivalenza", "evidence": "Risolvi e motiva un caso diverso da quelli del generatore.", "case": {"probe": "Calcola 1/6 + 1/3 e motiva.", "full": "«1/6 + 2/6 = 3/6 = 1/2. Le due forme sono equivalenti, quindi entrambe corrette.»", "partial": "«2/9.»", "why": "Somma numeratori e denominatori; inoltre il generatore deve accettare sia 3/6 sia 1/2, come stabilito nelle regole del dominio."}}, {"area": "Scienze e fisica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare conversioni tra unità con risultati indipendenti di controllo", "features": "Unità dichiarate, valori semplici e feedback dimensionale", "evidence": "Risolvi una conversione nuova mostrando il fattore usato.", "case": {"probe": "Converti 2,5 km in metri e 750 g in kilogrammi, mostrando il fattore usato.", "full": "«2,5 km × 1000 m/km = 2500 m; 750 g ÷ 1000 g/kg = 0,75 kg. Il fattore è 1000 in entrambi i casi, ma il verso dipende dall’unità di partenza.»", "partial": "«2500 m e 750 000 kg.»", "why": "Usa il fattore giusto nel verso sbagliato: manca il controllo dimensionale (passando a un’unità più grande il numero deve diminuire)."}}, {"area": "Arte e musica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare analisi di elementi formali con una banca controllata", "features": "Schede, indizi progressivi e rubrica per interpretazioni aperte", "evidence": "Motiva un’analisi usando elementi osservabili nel materiale.", "case": {"probe": "Scheda: «Notte stellata» di Vincent van Gogh (1889). Motiva un’analisi usando elementi osservabili.", "full": "«Le pennellate dense e curve creano un ritmo vorticoso nel cielo; il cipresso scuro in primo piano fa da asse verticale e contrasta con l’orizzontalità del paese.»", "partial": "«Il quadro esprime la follia del pittore.»", "why": "È un’interpretazione biografica non ancorata al dipinto: la rubrica chiede di partire da segno, colore e composizione."}}, {"area": "Informatica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare tracce di algoritmi con casi controllati", "features": "Esempi brevi, input validi e risultati verificati indipendentemente", "evidence": "Individua un caso limite e spiega il risultato atteso.", "case": {"probe": "L’algoritmo cerca il massimo in una lista di numeri. Individua un caso limite e il risultato atteso.", "full": "«La lista vuota: non esiste un massimo e l’algoritmo deve segnalarlo invece di restituire 0. Un altro caso: tutti valori negativi, dove partire da max = 0 darebbe un risultato sbagliato.»", "partial": "«Una lista molto lunga.»", "why": "Indica un caso grande, non un caso limite che mette in crisi la logica dell’algoritmo."}}, {"area": "Diritto ed economia", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare il calcolo e l’interpretazione della variazione percentuale di prezzi e redditi", "features": "Valori piccoli, arrotondamento dichiarato, segno della variazione e risultati verificati indipendentemente", "evidence": "Interpreta segno e ordine di grandezza di una variazione nuova.", "case": {"probe": "Un prezzo passa da 80 € a 60 €. Calcola e interpreta la variazione percentuale.", "full": "«(60 − 80) / 80 × 100 = −25%: il prezzo è diminuito di un quarto; il segno negativo indica una riduzione.»", "partial": "«−33%.»", "why": "Divide per il valore finale: la variazione percentuale si calcola sul valore iniziale."}}, {"area": "Disegno e storia dell’arte", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare la lettura delle scale di rappresentazione con risultati verificati", "features": "Scale dichiarate (1:50, 1:100, 1:200), misure in cm e m, tolleranza di arrotondamento dichiarata", "evidence": "Converti una misura nuova e motiva il passaggio.", "case": {"probe": "Su una pianta in scala 1:50 una parete misura 12 cm. Quanto è lunga in realtà?", "full": "«12 cm × 50 = 600 cm, cioè 6 m: in scala 1:50 ogni centimetro del disegno corrisponde a 50 cm reali.»", "partial": "«60 cm.»", "why": "Applica il fattore in modo errato e non controlla l’ordine di grandezza: una parete di una stanza lunga 60 cm non è plausibile."}}], "promptContrast": {"weak": "Aggiungi tante funzioni utili.", "reason": "Non sono indicati priorità, perimetro minimo e condizioni di correttezza."}, "schedule": "15 min · presentazione delle idee di project work · 20 min · scelta della versione minima e di ciò che resta fuori · 100 min · sviluppo assistito per iterazioni brevi · 10 min pausa · 40 min · revisione tra pari con registro dei test · 25 min · attività con studenti costruttori (modalità C) · 10 min pausa · 20 min · test finale.", "classroom": {"mode": "C", "modeLabel": "Modalità C · Gli studenti costruiscono", "title": "Coppie progettista e verificatore", "intro": "Con account istituzionali autorizzati, gli studenti dialogano con l’IA per costruire un piccolo strumento disciplinare. I ruoli separati rendono osservabili decisioni, prove e correzioni.", "steps": [["5 min · Obiettivo", "Ogni coppia scrive l’azione di apprendimento e la funzione minima dell’app."], ["10 min · Iterazione", "Il progettista scrive il prompt; il verificatore prepara prima tre test con risultato atteso."], ["10 min · Prova e correzione", "Si scambiano i ruoli dopo la prima versione: chi verifica descrive un difetto in modo riproducibile."], ["5 min · Registro", "Consegna di prompt, test e una decisione presa dalla coppia e non dall’IA."]], "assess": "Valuta il registro delle prove e la motivazione delle scelte; l’aspetto grafico dell’app non è un criterio."}}, {"title": "Validare, documentare e pianificare l’uso", "intro": "Controlla il tuo prodotto con criteri espliciti, correggi i difetti prioritari e prepara istruzioni comprensibili. Concludi con un piano di sperimentazione e il test finale del percorso.", "product": "Un prototipo documentato, un rapporto di verifica e un piano di utilizzo.", "goals": ["Distinguere difetti bloccanti e miglioramenti facoltativi.", "Documentare solo verifiche effettuate.", "Preparare una sperimentazione con evidenze osservabili."], "example": {"kind": "Revisione di un prototipo", "audience": "Utenti del prototipo realizzato", "goal": "Verificare che il prodotto sostenga l’obiettivo dichiarato e sia utilizzabile", "features": "Checklist di test, priorità dei difetti, scheda d’uso, limiti noti e piano di sperimentazione senza dati personali"}, "steps": [{"title": "1. Confronta risultato e obiettivo", "explain": "Un prototipo piacevole può non esercitare la competenza prevista. Usa la specifica iniziale come riferimento e controlla i comportamenti reali.", "prompt": "Rivedi questo prototipo rispetto a obiettivo [obiettivo], utenti [destinatari] e requisiti [elenco]. Prepara una matrice requisito, evidenza necessaria e prova. Distingui analisi del codice e comportamento verificato nel browser. Non inventare esiti.", "action": "Raccogli una prova per ogni requisito essenziale.", "check": "Ogni affermazione di funzionamento ha un’evidenza o è indicata come da verificare."}, {"title": "2. Ordina i difetti per impatto", "explain": "Un punteggio sbagliato può impedire l’obiettivo; un colore migliorabile può aspettare. Stabilisci priorità motivate.", "prompt": "Organizza questi rilievi [elenco] in bloccanti, importanti e facoltativi. Motiva la priorità in relazione a correttezza, compito principale, accessibilità e dati. Proponi la correzione minima per il primo difetto.", "action": "Correggi prima un problema che impedisce l’uso e ripeti le prove.", "check": "Non confondi la gravità del difetto con la facilità della correzione."}, {"title": "3. Esegui un test incrociato", "explain": "Fai usare la versione aggiornata a una persona senza guidarla a ogni click. Segna comportamenti osservati, non supposizioni.", "prompt": "Prepara tre compiti per un test con un’altra persona e una griglia con passaggi, risultato atteso, osservato e ostacoli. Includi un errore dell’utente e una ripresa dell’attività. Non inserire nomi reali nella griglia dimostrativa.", "action": "Osserva l’uso, poi chiedi dove l’utente si è fermato e perché.", "check": "Il rapporto distingue ciò che è stato osservato dalle interpretazioni."}, {"title": "4. Scrivi una scheda d’uso e i limiti", "explain": "Una buona documentazione permette di iniziare senza conoscere il progetto. Spiega apertura, azioni, riavvio, dati salvati e limiti.", "prompt": "Scrivi una scheda d’uso per [utenti] del prototipo [descrizione]. Includi obiettivo, come aprirlo, tre azioni iniziali, gestione degli errori, dati eventualmente salvati e dove, limiti noti e come segnalare un difetto. Non promettere funzioni non implementate.", "action": "Fai leggere la scheda a un’altra persona e chiedile di iniziare l’attività.", "check": "La scheda corrisponde alla versione effettivamente consegnata."}, {"title": "5. Pianifica la sperimentazione e chiudi il percorso", "explain": "Scegli un’attività breve e un’evidenza collegata all’obiettivo. Il gradimento non dimostra da solo l’apprendimento.", "prompt": "Proponi una sperimentazione breve per [obiettivo e destinatari]. Specifica attività, durata, evidenza osservabile, criteri di successo e alternativa in caso di problema tecnico. Raccogli solo dati necessari e descrivi ciò che resterà da verificare dopo la prova.", "action": "Prepara il piano e confronta il prodotto finale con il bisogno iniziale.", "check": "Sai spiegare come osserverai l’apprendimento e che cosa farai se l’app non è disponibile."}], "quiz": [{"case": "Il prototipo supera tutti i test tecnici e piace ai colleghi. Che cosa non sai ancora?", "options": ["Nulla di essenziale: funzionamento e gradimento sono le due verifiche principali.", "Se il contenuto è corretto e se l’attività aiuta a raggiungere l’obiettivo.", "Solo se l’app funziona anche su tablet e su schermi molto piccoli.", "Se il codice rispetta le buone pratiche della programmazione professionale."], "correct": 1, "feedback": "Funziona? È corretto? Aiuta ad apprendere? Sono tre verifiche diverse.", "hint": "Ripensa alle tre domande di validazione della lezione.", "why": ["Il test tecnico e il gradimento da soli non dimostrano apprendimento.", "", "È un controllo tecnico in più, non la verifica che manca.", "La qualità del codice non dice nulla sull’efficacia didattica."]}, {"case": "Hai tre difetti: il punteggio è sbagliato dopo il riavvio, un colore è poco elegante, c’è un refuso in una consegna. In che ordine li affronti?", "options": ["Colore, refuso, punteggio: prima ciò che gli studenti notano subito aprendo l’app.", "Punteggio, refuso, colore: prima ciò che compromette obiettivo e correttezza.", "Refuso, colore, punteggio: prima le correzioni più rapide da fare.", "Tutti insieme in un unico prompt, per non perdere tempo."], "correct": 1, "feedback": "Le priorità seguono l’impatto sull’obiettivo: un punteggio sbagliato invalida l’attività.", "hint": "Quale difetto impedisce di usare l’app per il suo scopo?", "why": ["La visibilità non coincide con l’impatto sull’apprendimento.", "", "La rapidità non è un criterio di priorità.", "Tre modifiche insieme rendono difficile verificarle."]}, {"case": "Durante il test incrociato il collega si blocca su una schermata. Che cosa fai?", "options": ["Gli spieghi dove cliccare, così il test può proseguire senza perdere tempo.", "Non intervieni: annoti dove si è bloccato e che cosa ha provato a fare.", "Interrompi il test e correggi subito il punto critico.", "Gli mostri prima un video dimostrativo e poi fate ripartire la prova."], "correct": 1, "feedback": "Il blocco è il dato più prezioso del test: va osservato e registrato, non risolto al posto suo.", "hint": "Che cosa succederà quando lo studente userà l’app senza di te?", "why": ["Guidandolo nascondi proprio l’ostacolo che il test doveva rivelare.", "", "Correggere durante la prova ti fa perdere le osservazioni successive.", "Il video cambia le condizioni della prova rispetto all’uso reale."]}, {"case": "Quale frase può comparire correttamente in un rapporto di verifica?", "options": ["L’app è accessibile e funziona correttamente su tutti i dispositivi e su tutti i browser.", "Provata da tastiera su Chrome per PC e su un Android: navigazione completa; iPhone non provato.", "L’assistente IA ha confermato, dopo un controllo accurato, che il codice è privo di errori.", "Durante l’uso in classe gli studenti non hanno rilevato problemi di alcun tipo."], "correct": 1, "feedback": "Il rapporto distingue prove eseguite, risultati osservati e verifiche ancora aperte.", "hint": "Quale frase un collega potrebbe controllare ripetendo le stesse prove?", "why": ["Una promessa generale: non dice quali prove sono state fatte.", "", "Una dichiarazione dell’IA non è una verifica eseguita.", "Non indica quali prove, su che cosa e con quali condizioni."]}, {"case": "Perché nel rapporto di verifica indichi la versione del file che hai provato?", "options": ["Per rispettare una formalità richiesta dalla documentazione finale del corso.", "Perché un collega possa ripetere le stesse prove sullo stesso prodotto.", "Perché l’IA possa rigenerare in futuro la stessa identica versione.", "Per documentare il tempo dedicato al progetto."], "correct": 1, "feedback": "La revisione deve poter essere ripetuta da un collega sulla stessa versione del prodotto.", "hint": "Che cosa succede se il collega prova una versione diversa?", "why": ["Non è una formalità: senza versione le prove non sono confrontabili.", "", "L’IA non rigenera versioni identiche: la versione serve a chi verifica.", "La versione non misura il tempo di lavoro."]}, {"case": "Che cosa deve contenere la scheda d’uso per gli studenti?", "options": ["La descrizione tecnica del codice, delle librerie utilizzate e della loro versione.", "Come aprire l’app, che cosa fare, come ricominciare, quali dati salva e i limiti.", "La storia del progetto e l’elenco completo dei prompt usati per costruirlo.", "Un invito a segnalare direttamente all’IA eventuali errori riscontrati."], "correct": 1, "feedback": "Una buona scheda permette di iniziare senza conoscere il progetto.", "hint": "Che cosa serve a uno studente che apre l’app per la prima volta?", "why": ["Lo studente non ha bisogno dei dettagli tecnici per usare l’app.", "", "Prompt e storia del progetto servono al docente, non allo studente.", "Le segnalazioni vanno al docente, che è responsabile del prodotto."]}, {"case": "Quale indicatore mostra che l’attività ha aiutato a raggiungere l’obiettivo?", "options": ["Il 90% degli studenti dichiara nel questionario che l’app è piaciuta.", "Gli studenti risolvono senza l’app un caso nuovo, motivando la scelta.", "Gli studenti completano il quiz in meno di dieci minuti, senza aiuto.", "Il punteggio medio ottenuto dalla classe nell’app è stato di 9 su 10."], "correct": 1, "feedback": "L’evidenza di apprendimento si osserva su un caso nuovo, fuori dall’app.", "hint": "Quale dato non dipende dall’app né dal ricordo delle sue domande?", "why": ["Il gradimento non dimostra da solo l’apprendimento.", "", "La velocità non dice nulla sulla comprensione.", "Un punteggio alto nell’app può dipendere dalla memoria delle domande o da tentativi ripetuti."]}, {"case": "Il giorno della prova il laboratorio informatico non è disponibile. Che cosa prevedeva un buon piano?", "options": ["Rinviare l’attività alla prima settimana libera del laboratorio.", "Un’alternativa senza dispositivi, con gli stessi casi e lo stesso obiettivo.", "Far usare agli studenti i propri telefoni, collegati con la connessione personale di ciascuno.", "Proiettare un video dell’app al posto dell’attività."], "correct": 1, "feedback": "L’alternativa tecnica garantisce l’obiettivo anche quando gli strumenti mancano.", "hint": "Che cosa deve restare uguale anche senza computer?", "why": ["Il rinvio sposta il problema e interrompe la progettazione didattica.", "", "Usare dispositivi e connessioni personali richiede regole e consensi della scuola.", "Guardare un video non sostituisce l’attività degli studenti."]}, {"case": "Come presenti al dirigente la scheda di sperimentazione prodotta nel corso?", "options": ["Come una certificazione UNESCO delle competenze di IA possedute dal docente.", "Come un’attività del corso coerente con il quadro UNESCO, non una certificazione.", "Come un documento obbligatorio richiesto dall’AI Act a ogni docente che usa l’IA.", "Come una validazione ufficiale dell’app da parte del Ministero dell’istruzione."], "correct": 1, "feedback": "Il quadro UNESCO è un riferimento; la scheda è un’attività del corso.", "hint": "Chi ha emesso la scheda?", "why": ["La scheda non è emessa né riconosciuta dall’UNESCO.", "", "L’AI Act chiede alfabetizzazione, non questa scheda specifica.", "Il Ministero non ha validato l’app."]}, {"case": "Quale piano di sperimentazione è più solido?", "options": ["Uso dell’app per un mese con tutte le classi e un questionario di gradimento alla fine dell’anno.", "Prova di 30 minuti in una classe, un indicatore legato all’obiettivo e un’alternativa tecnica.", "Pubblicazione dell’app sul sito della scuola e raccolta spontanea dei commenti di chi la usa.", "Confronto tra il punteggio nell’app e i voti dell’ultima verifica di ogni studente."], "correct": 1, "feedback": "Una prova breve e circoscritta, con un’evidenza legata all’obiettivo, è osservabile e ripetibile.", "hint": "Quale piano raccoglie un’evidenza di apprendimento in modo controllabile?", "why": ["Esteso e basato sul gradimento: costoso e poco informativo sull’apprendimento.", "", "I commenti spontanei non sono un’evidenza legata all’obiettivo.", "Incrocia dati personali senza necessità e confronta prove non comparabili."]}], "id": 6, "version": 3, "concepts": [{"title": "Tre domande di validazione", "text": "Il prodotto funziona? Il contenuto è corretto? L’attività aiuta a raggiungere l’obiettivo? Sono verifiche diverse. Il test tecnico e il gradimento da soli non dimostrano apprendimento."}, {"title": "L’evidenza viene prima della promessa", "text": "Nel rapporto distingui prove eseguite, risultati osservati e verifiche ancora aperte. La revisione deve poter essere ripetuta da un collega sulla stessa versione del prodotto."}, {"title": "Dalla formazione alla tua classe", "text": "Prepara una prova breve, un indicatore collegato all’obiettivo e un’alternativa tecnica. Il quadro UNESCO per i docenti collega competenze di IA, pedagogia, responsabilità e autonomia professionale [2]. La scheda qui proposta è un’attività del corso, non una certificazione UNESCO."}], "disciplineExamples": [{"area": "Italiano", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare correttezza dei feedback e qualità delle argomentazioni richieste", "features": "Test tecnico e rubrica per motivazioni aperte, con revisione del docente", "evidence": "Confronta una risposta iniziale e una risposta finale su testi diversi.", "case": {"probe": "Prima dell’uso dell’app lo studente ha scritto, sul testo A: «L’autore dice che i social sono negativi». Dopo, sul testo B, diverso, scrive la sua analisi.", "full": "Sul testo B la risposta individua la tesi e gli argomenti e li collega; sul testo A si limitava a parafrasare. La rubrica registra un passaggio di livello nel criterio «struttura».", "partial": "«La risposta finale è più lunga e più ordinata.»", "why": "Lunghezza e ordine non sono criteri della rubrica: servono testi diversi e un criterio esplicito."}}, {"area": "Storia e filosofia", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare provenienza delle fonti e pluralità delle interpretazioni", "features": "Verifica dei link, contestualizzazione e rubrica argomentativa", "evidence": "Sostieni una lettura con una fonte e formula un’obiezione.", "case": {"probe": "Lettura proposta: «Il Risorgimento fu soprattutto opera delle élite». Sostienila con una fonte e formula un’obiezione.", "full": "«La sostengo con i dati elettorali del 1861: votava circa il 2% della popolazione. Obiezione: la partecipazione di volontari di origine popolare alla spedizione dei Mille.»", "partial": "«È vero, perché lo dice il manuale.»", "why": "Sostituisce la fonte con un’autorità e non formula alcuna obiezione."}}, {"area": "Lingue straniere", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare livello, naturalezza e correttezza del feedback linguistico", "features": "Casi attesi, alternative corrette e revisione umana delle produzioni aperte", "evidence": "Confronta produzioni iniziali e finali con una rubrica di appropriatezza.", "case": {"probe": "Produzione iniziale e finale: un’email di scuse per una risposta in ritardo.", "full": "Iniziale: «Sorry, I am late». Finale: «I’m sorry I couldn’t reply sooner — I was away until Monday». Con la rubrica di appropriatezza si vede il progresso: motivazione esplicita e registro adatto al destinatario.", "partial": "«La finale non ha errori di grammatica, quindi è migliorata.»", "why": "La correttezza grammaticale è un solo criterio: la rubrica chiede l’adeguatezza al contesto comunicativo."}}, {"area": "Matematica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare formule, casi limite e spiegazioni matematiche", "features": "Risultati calcolati indipendentemente e input non ammessi", "evidence": "Individua un errore in una soluzione e giustifica la correzione.", "case": {"probe": "Soluzione da controllare: «(x + 3)² = x² + 9».", "full": "«Manca il doppio prodotto: (x + 3)² = x² + 6x + 9. Verifica con x = 1: 16 contro 10.»", "partial": "«È sbagliata, il risultato è diverso.»", "why": "Individua l’errore ma non dice dove sia né giustifica la correzione."}}, {"area": "Scienze e fisica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare modelli, unità e limiti delle conclusioni", "features": "Casi di riferimento e distinzione tra dato e interpretazione", "evidence": "Spiega che cosa il modello può e non può sostenere.", "case": {"probe": "Il simulatore dice che un’auto a 30 m/s percorre 1080 km in 10 ore. Che cosa può sostenere il modello?", "full": "«Il calcolo è coerente con s = v × t, ma il modello assume velocità costante per 10 ore: non può prevedere un viaggio reale con soste e accelerazioni.»", "partial": "«Il risultato è giusto, quindi il simulatore descrive bene il viaggio.»", "why": "Confonde la correttezza del calcolo con la validità del modello rispetto al fenomeno reale."}}, {"area": "Arte e musica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare attribuzioni, crediti e qualità dei criteri di analisi", "features": "Verifica dei materiali e revisione umana delle interpretazioni", "evidence": "Confronta due analisi rispetto a una griglia esplicita.", "case": {"probe": "Due analisi dello stesso paesaggio: A «Mi trasmette calma»; B «La composizione orizzontale e i colori freddi poco saturi creano un’atmosfera calma». Confrontale con la griglia.", "full": "«B è più forte rispetto alla griglia (composizione, colore, luce): collega l’effetto a elementi osservabili. A esprime un’impressione legittima ma non verificabile.»", "partial": "«B è migliore perché usa parole tecniche.»", "why": "Il lessico specialistico non basta: conta il legame tra elemento osservabile ed effetto."}}, {"area": "Informatica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare comportamento, accessibilità e dati di un’app", "features": "Test riproducibili e documentazione delle funzioni effettive", "evidence": "Riproduci un difetto e giustifica la modifica minima.", "case": {"probe": "Segnalazione ricevuta: «Il quiz a volte dà un punteggio sbagliato».", "full": "Riproduce il difetto con passaggi precisi (errata la 1, corretta la 2, riavvio, corretta la 1: punteggio 2 invece di 1), individua che il riavvio non azzera il punteggio e propone di azzerarlo solo nella funzione di riavvio.", "partial": "Fa riscrivere tutta l’app all’IA e il difetto non compare più.", "why": "Senza riproduzione non si sa se il difetto è risolto o solo nascosto, e la modifica non è minima."}}, {"area": "Diritto ed economia", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare correttezza e aggiornamento dei riferimenti normativi di un’app", "features": "Controllo degli articoli sul testo vigente in Normattiva, data di consultazione, distinzione tra norma e commento", "evidence": "Individua un riferimento superato e indica la fonte ufficiale corretta.", "case": {"probe": "L’app indica l’art. 18 dello Statuto dei lavoratori come tutela per tutti i licenziamenti illegittimi.", "full": "«Su Normattiva verifico che l’art. 18 è stato modificato dalla L. 92/2012 e che per gli assunti dal 7 marzo 2015 si applica il D.Lgs. 23/2015. Segnalo il riferimento come superato e indico il testo vigente con la data di consultazione.»", "partial": "«Il riferimento è giusto perché l’art. 18 esiste ancora.»", "why": "Che un articolo esista non significa che il contenuto citato sia ancora vigente: servono il testo aggiornato e la data di consultazione."}}, {"area": "Disegno e storia dell’arte", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare attribuzioni, datazioni e diritti delle immagini in un’app di storia dell’arte", "features": "Controllo delle schede su fonti museali o istituzionali, licenze delle immagini, distinzione tra dato e interpretazione", "evidence": "Individua un dato o una licenza errata e indica la fonte corretta.", "case": {"probe": "La scheda dell’app riporta: «Cupola di Santa Maria del Fiore, Filippo Brunelleschi, completata nel 1536». La foto è presa da un sito senza indicazione di licenza.", "full": "«La data è errata: la cupola fu costruita tra il 1420 e il 1436, la lanterna fu completata più tardi; lo verifico sul sito dell’Opera di Santa Maria del Fiore. La foto va sostituita con un’immagine in licenza aperta, citando autore e licenza.»", "partial": "«La scheda va bene, perché l’autore è corretto.»", "why": "Controlla un solo dato su tre: anche la data e i diritti dell’immagine fanno parte della revisione."}}], "promptContrast": {"weak": "Dimmi se va tutto bene.", "reason": "Non sono dichiarati requisiti, prove eseguite e limiti da verificare."}, "schedule": "20 min · rapporto di verifica: funziona, è corretto, aiuta ad apprendere? · 70 min · test incrociati e correzione dei difetti bloccanti · 10 min pausa · 40 min · scheda d’uso per gli studenti e piano di sperimentazione · 40 min · presentazione dei prototipi ai colleghi · 10 min pausa · 30 min · test finale e restituzione del percorso · 20 min · questionario e prossimi passi.", "classroom": {"mode": "B", "modeLabel": "Modalità B · La classe collauda e documenta", "title": "Gli studenti come collaudatori", "intro": "Prima dell’uso esteso, una classe pilota prova l’app con una checklist. Le osservazioni degli studenti diventano evidenze per il rapporto di verifica e per il piano di sperimentazione.", "steps": [["5 min · Consegna", "Distribuisci una checklist breve: funziona, è chiaro, mi ha aiutato a capire?"], ["10 min · Collaudo", "Gli studenti usano l’app su dispositivi diversi e segnalano ogni difetto con passaggi riproducibili."], ["10 min · Prova di apprendimento", "Proponi un caso nuovo senza l’app e confronta le risposte con l’obiettivo."], ["5 min · Sintesi", "Ordina le segnalazioni in bloccanti e migliorative e decidi che cosa correggere."]], "assess": "Tieni separati esito tecnico, gradimento e prova di apprendimento: sono tre evidenze diverse."}}];
